(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["de-CH"] = {"ui":{"skip":"Zum Inhalt springen","back":"← Zurück zu AI-gile","lang.button":"Sprache: {name}","lang.dialog":"Sprache wählen","lang.search":"Sprachen suchen","lang.none":"Keine Sprache gefunden","lang.notYet":"{name} ist noch nicht übersetzt","theme.aria":"Design wechseln: hell, dunkel oder schwarz","theme.toLight":"Zum hellen Design wechseln","theme.toDark":"Zum dunklen Design wechseln","theme.toBlack":"Zum schwarzen Design wechseln (echtes Schwarz, schont OLED-Bildschirme)","words.underline":"Diese Wörter auf der Seite unterstreichen","words.underlineHelp":"Fahr mit der Maus über ein gepunktetes Wort oder tippe darauf, um zu sehen, was es bedeutet.","words.col.todo":"Karten, die für jetzt ausgewählt sind: Das Team fängt als Nächstes mit diesen an.","words.col.doing":"Eine KI arbeitet gerade an dieser Karte.","words.col.review":"Eine KI hat die Arbeit erledigt; eine andere prüft sie, bevor sie bei dir ankommt.","words.col.verify":"Wartet auf dich: Probier es aus und sag, ob es funktioniert.","words.col.team":"Deine Notizen oder Antworten, die darauf warten, dass das Team sie aufgreift.","words.col.done":"Fertig und abgenommen.","index.title":"AI-gile: dein KI-Entwicklerteam auf einem Board","index.description":"AI-gile ist ein Kanban-Board für KI-Coding-Teams. Sie arbeiten, während du schläfst; du bekommst einen kurzen Stapel zum Entscheiden, Testen und Abnehmen.","hero.logoAlt":"AI-gile-Board-Symbol","hero.h1.html":"Dein KI-Entwicklerteam auf einem&nbsp;Board.","hero.alpha":"🐣 Geschlossene Pre-Alpha","hero.alphaTitle":"Früh und unfertig: danke fürs Ausprobieren!","hero.lede":"Sie bauen, während du schläfst. Du wachst auf und findest einen kurzen Stapel: ein paar Fragen, ein paar Dinge zum Testen, ein oder zwei lila Rauten. Klicken, abnehmen, zurück zum Kaffee.","dl.windows":"Windows-App","dl.browser":"Im Browser starten","dl.messenger":"📱 Messenger fürs Handy","dl.soon":"Bald verfügbar","dl.notify":"🔔 Sag mir Bescheid, wenn es losgeht","dl.notifySmall":"Alpha oder Beta","hero.secondary":"Agil, aber das Team braucht nie einen Stand-up-Kaffee. (Stand-ups machen sie trotzdem.)","pitch.h2":"AI-gile in so vielen Wörtern, wie du magst","pitch.lede":"Wähle eine Länge, von einem Wort bis 144. Jede Länge ist eine eigene Beschreibung, geschrieben für genau diese Grösse. Zieh den Regler oder nimm die Pfeiltasten.","pitch.rangeLabel":"Länge in Wörtern","pitch.dice":"🎲 noch eine Version","pitch.words.one":"{n} Wort","pitch.words.other":"{n} Wörter","pitch.letters.one":"{n} Buchstabe","pitch.letters.other":"{n} Buchstaben","pitch.chars.one":"{n} Zeichen","pitch.chars.other":"{n} Zeichen","count.line.html.one":"{n} Karte gerade auf dem Board","count.line.html.other":"{n} Karten gerade auf dem Board","people.humans.html.one":"👥 {n} Mensch","people.humans.html.other":"👥 {n} Menschen","people.agents.html.one":"🤖 {n} Agent","people.agents.html.other":"🤖 {n} Agenten","people.working.html.one":"⚡ {n} gerade am Werk","people.working.html.other":"⚡ {n} gerade am Werk","pre.title":"AI-gile: Hier entsteht etwas","pre.description":"Hier entsteht gerade etwas. Ein Board, auf dem KI-Teams bauen, worum du sie bittest, und dir dabei einiges beibringen. Vorerst eine geschlossene Pre-Alpha mit Freunden.","pre.h1":"Hier entsteht gerade etwas. 🤫","pre.line":"Ein Board, auf dem KI-Teams bauen, worum du sie bittest, und dir dabei einiges beibringen. Vorerst eine geschlossene Pre-Alpha mit Freunden.","pre.btn":"🔔 Sag mir Bescheid, wenn es losgeht","pre.peek":"Hinter dem Glas: das echte Board, live. Jede Karte ist ein farbiger Balken.","pre.peekFake":"Hinter dem Glas: So sieht ein Board bei der Arbeit aus.","pre.night":"🌙 Der Nachtwächter het d'Zügel i de Hand · 😴 de Mänsch ruht sich us","features.aria":"Was es kann","f.pile.h":"Ein Stapel für dich","f.pile.html":"<b>Für dich</b> sammelt alles, was auf dich wartet, über alle Projekte hinweg: Fragen, Dinge zum Testen, Aufgaben, die nur ein Mensch erledigen kann. Deine Warteschlange sagt, was als Nächstes dran ist und wie lange es dauert.","f.sleep.h":"Teams, die arbeiten, während du schläfst","f.sleep.p":"Jedes Projekt hat einen Lead und ein Team aus KI-Agenten. Kommentiere eine Karte, und das Team wacht auf, erledigt die Arbeit und gibt sie zurück, mit Schritten, die auch ein müder Mensch versteht.","f.tester.h":"Zuerst prüft ein KI-Tester","f.tester.p":"Bevor etwas bei dir landet, folgt ein Tester den Schritten in einer Kopie der App und zeigt mit einem Screenshot, was er gesehen hat. Blättere durch die bestandenen und nimm sie mit einem Klick ab.","f.proof.h":"Belege statt Versprechen","f.proof.p":"Jede Übergabe zeigt, was sich geändert hat: die Dateien, den Diff, die Screenshots. Du musst nicht jede App öffnen, um zu sehen, ob es fertig ist.","f.chat.h":"Chatte mit deinen Leads","f.chat.p":"Eine Leiste wie bei Discord: ein Symbol pro Projekt, lila Rauten für alles, was dich braucht. Schreib einem Lead eine Idee; er macht daraus Karten und einen Plan, mit einem ✅ Los-Knopf.","f.tidy.h":"Hält sich selbst in Ordnung","f.tidy.p":"Verwandte Karten werden zu einer, wirre Titel werden repariert, und ein Token-Check hält den Code schlank. Weniger, zwischen dem du wechseln musst, weniger zum Nachdenken.","f.private.h":"Deins, auf deinem Computer","f.private.li1":"Das Board läuft auf deinem eigenen Rechner und antwortet nur dir.","f.private.li2":"Private Nachrichten zwischen Menschen sind Ende-zu-Ende-verschlüsselt.","f.private.li3":"Keine Konten, keine Tracker, keine Cookies.","f.lang.h":"In deiner Sprache","f.lang.p":"Über 120 Sprachen, von Niederländisch, Walisisch und Japanisch bis Piratisch, Yoda und Klingonisch, mit einem schnellen Wechsel zurück zu Englisch für die Fachbegriffe.","f.service.h":"Von der Idee zum echten Service","f.service.p":"Mit KI etwas gebaut, das Leute jetzt nutzen? Markiere es als Service, und das Board hilft dir, es gut zu betreiben: Uptime-Checks, eine öffentliche Statusseite, Vorfälle mit Nachbetrachtung, Änderungen, die ein Go brauchen, täglich geprüfte Sicherungen. Die Hilfe erklärt jeden Schritt, während du vorangehst.","msgr.h2":"AI-gile Messenger: dein Team in der Hosentasche","msgr.p1":"Sprich mit deinem KI-Team, ohne das Board zu öffnen. Chatte mit deinen Projektleads und deinen Freunden, sieh dir die Testschritte einer Karte an und beantworte sie, alles vom Handy aus.","msgr.p2":"Zum Koppeln scannst du einen QR-Code auf deinem Board. Zum ersten Mal da? Ein freundlicher Demo-Chat zeigt dir alles.","msgr.when":"Zuerst für Android, danach eine Web-Version für Handys und iPhone.","msgr.who":"Dein Projektlead","msgr.b1":"Der Fix für den Dunkelmodus ist fertig. Willst du die Testschritte?","msgr.b2":"Ja, gern!","msgr.b3":"1. Öffne Einstellungen. 2. Wähl Dunkel. Sieht es richtig aus?","tl.aria":"Zeitleiste vom ersten Gespräch bis zur Roadmap","tl.h2":"Vom ersten Chat bis zu dem, was kommt","tl.lede":"Echte Daten und Uhrzeiten, in deiner eigenen Zeitzone. Nach heute ist es der Plan, ohne versprochene Termine.","tl.today":"Heute","tl.planned":"geplant","tl.doing":"in Arbeit","tl.cards.one":"{n} Karte","tl.cards.other":"{n} Karten","join.h2":"Mach mit","join.lede":"AI-gile wird von einem bärtigen Kauz mit AuDHD und ein paar Kämpfen mit der psychischen Gesundheit gebaut, zusammen mit sehr vielen geduldigen Agenten. Vorerst ist es privat, in einer geschlossenen Alpha mit Freunden. Lust auf einen Versuch, wenn es sich öffnet?","join.btn":"Interesse anmelden","join.small":"Wir mailen dir, sonst nichts","footer.tag":"AI-gile. Keine Tracker, keine Cookies, kein Stand-up-Kaffee.","footer.licence":"Geschäftslizenz","footer.status":"Status","footer.privacy":"Was wir speichern","footer.thanks":"Anrufe dank ChilledChat","form.sending":"Wird gesendet…","form.failed":"Das hat nicht geklappt: versuch es später noch einmal.","form.offline":"AI-gile ist nicht erreichbar: versuch es später noch einmal.","form.keep":"Wir nutzen das nur, um dir zu antworten, und löschen es danach. Keine Tracker, keine Cookies.","form.keepLink":"Was wir speichern","interest.title":"AI-gile: sag mir Bescheid, wenn die Alpha startet","interest.description":"Hinterlasse deine E-Mail-Adresse, um zu erfahren, wann die geschlossene Alpha oder Beta von AI-gile startet.","interest.h1":"🔔 Sag mir Bescheid, wenn es losgeht","interest.lede":"AI-gile ist in der geschlossenen Pre-Alpha. Hinterlasse deine E-Mail-Adresse, und wir schreiben dir einmal, wenn ein Platz für dich frei ist.","interest.email":"Dein E-Mail","interest.which":"Welcher Test?","interest.alpha":"Geschlossene Alpha: früh, rau, viele Änderungen","interest.beta":"Beta: stabiler, später","interest.both":"Egal, was zuerst kommt","interest.submit":"Trag mich in die Liste ein","interest.thanks":"Danke! Du stehst auf der Liste.","licence.title":"AI-gile: Geschäftslizenz","licence.description":"Du nutzt AI-gile in deinem Unternehmen? Beantrage eine kostenlose Geschäftslizenz.","licence.h1":"📜 Geschäftslizenz","licence.lede":"Du nutzt AI-gile bei der Arbeit? Erzähl uns, wer du bist und was du machst. Wenn es etwas Gutes bewirkt, ist die Lizenz kostenlos.","licence.company":"Unternehmen","licence.website":"Website","licence.what":"Was du machst","licence.how":"Wie es der Welt hilft","licence.email":"E-Mail","licence.submit":"Beantragen","licence.thanks":"Danke! Wir antworten per E-Mail.","status.title":"AI-gile-Status","status.h1":"AI-gile-Status","status.quiet":"Alles ruhig","status.intro":"Läuft AI-gile gerade? Diese Seite prüft alle 5 Minuten die Website, das Teilen von Boards, Anrufe und den Download.","status.up":"Läuft (Antwort in {ms} ms)","status.slow":"Hat bei der letzten Prüfung nicht geantwortet, neuer Versuch läuft","status.down":"Ausgefallen: hat bei den letzten zwei Prüfungen nicht geantwortet","status.svc.web":"Website","status.svc.web.offers":"Diese Seite: was AI-gile ist, und das Interessenformular","status.svc.boards":"Boards teilen","status.svc.boards.offers":"Öffentliche Boards, Nachrichten unter Freunden und Einladungen","status.svc.calls":"Anrufe","status.svc.calls.offers":"Audio, Video und Bildschirmfreigabe in AI-gile","status.svc.download":"Download","status.svc.download.offers":"Das Windows-Installationsprogramm und Einladungslinks","status.checking":"Wird geprüft…","status.offline":"Der Status-Dienst ist gerade nicht erreichbar (neuer Versuch folgt)","status.updated":"aktualisiert {ago}","status.justNow":"gerade eben","status.min":"vor {n} Min.","status.hours":"vor {n} Std.","status.days":"vor {n} T.","privacy.title":"AI-gile: was wir speichern","privacy.h1":"Was wir speichern","privacy.lede":"Kurz gesagt: nur das, was du uns schickst, und nicht lange.","privacy.only":"Nur das, was du uns schickst: was du in ein Formular eingibst, zum Beispiel deine E-Mail-Adresse. Sonst nichts über dich.","privacy.sealed":"Es wird versiegelt, damit unser Server es nicht lesen kann: schon in deinem Browser, bevor es losgeschickt wird (bei einem älteren Browser in dem Moment, in dem es ankommt). Nur unser eigenes Board kann es öffnen.","privacy.server":"Sobald es unser Board erreicht, wird es vom Server gelöscht. Was nach 30 Tagen noch dort liegt, wird sowieso gelöscht.","privacy.board":"Auf unserem Board behalten wir es nur, bis wir dir geantwortet haben, dann löschen wir es auch dort.","privacy.none":"Keine Tracker, keine Cookies, keine Analyse-Tools.","privacy.local":"Deine Sprache und deine Wahl zwischen hell und dunkel bleiben in deinem eigenen Browser. Sie werden nie an uns geschickt.","privacy.ask":"Soll es früher weg sein? Antworte auf unsere E-Mail und sag Bescheid.","live.h2":"Live zuschauen, wie es gebaut wird","live.caption":"Jede Karte ist verborgen: Du siehst die Form der Arbeit, nicht die Worte.","live.watching.one":"live: {n} schaut zu","live.watching.other":"live: {n} schauen zu","live.last.now":"Letzte Karte gerade eben verschoben","live.last.min.one":"Letzte Karte vor {n} Min. verschoben","live.last.min.other":"Letzte Karte vor {n} Min. verschoben","live.last.hour.one":"Letzte Karte vor {n} Stunde verschoben","live.last.hour.other":"Letzte Karte vor {n} Stunden verschoben","live.last.day.one":"Letzte Karte vor {n} Tag verschoben","live.last.day.other":"Letzte Karte vor {n} Tagen verschoben","live.offline":"Das Live-Board macht kurz Pause. Schau bald wieder vorbei.","live.cols":"Backlog|Zu tun|In Arbeit|Team prüft|Zum Testen für dich|Fürs Team|Erledigt","footer.models":"AI-gile lässt KI-Modelle für dich arbeiten. Was sie sagen und tun, geht auf ihre Rechnung, also prüf es, bevor du dich darauf verlässt.","privacy.ai.h":"Der KI-Teil","privacy.ai.models":"AI-gile ist das Board. Die Arbeit machen KI-Modelle anderer Firmen, etwa Claude, Codex und Gemini, über deine eigenen Konten.","privacy.ai.check":"Was sie schreiben und tun, kommt von ihnen und kann falsch sein. Prüf es, bevor du dich darauf verlässt oder es veröffentlichst.","privacy.ai.files":"Sie ändern Dateien und führen Befehle in den Ordnern aus, die du verbindest. Mach ein Backup.","privacy.ai.send":"Was du einem Modell gibst, geht an die Firma, die es betreibt, nach deren Bedingungen. Es gelten die Bedingungen und Kosten des jeweiligen Anbieters.","privacy.ai.asis":"AI-gile ist eine frühe Testversion, so wie sie ist."},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Roboter.","Delegiert."]},{"n":2,"texts":["Kanban, automatisiert.","Agenten, geordnet.","Ideen, gebaut."]},{"n":3,"texts":["Kanban für Roboter.","Ideen werden Features.","Kostenloses Kanban, lokal."]},{"n":5,"texts":["Ein Kanban-Board, das Agenten abarbeiten.","Du schreibst Karten. Agenten bauen.","Kostenlos, lokal, getestet, leicht albern."]},{"n":8,"texts":["Ein kostenloses Kanban-Board, auf dem KI-Agenten richtig arbeiten.","Schreib eine Idee. Agenten bauen sie. Du nimmst ab.","Agil für einen Menschen und viele geduldige Roboter."]},{"n":13,"texts":["Ein Kanban-Board auf deinem Computer, bei dem KI-Agenten die Karten übernehmen und abarbeiten.","Schreib eine Idee. Ein Agententeam baut sie. Ein Tester prüft sie. Du sagst Ja.","Kostenlos, ohne Konten, ohne Tracker: ein Board, ein paar Roboter, und du hast das Sagen."]},{"n":21,"texts":["AI-gile ist ein Kanban-Board für die Arbeit mit KI-Coding-Agenten. Sie übernehmen die Karten; du testest sie und nimmst sie ab.","Jedes Projekt bekommt einen Lead und ein Team aus KI-Agenten. Kommentiere irgendeine Karte, und schon legt das Team los.","Ein kostenloses, persönliches To-do-Board, das auf deinem eigenen Computer läuft. Die Arbeiter sind Roboter. Wer Ja sagt, bist du."]},{"n":34,"texts":["Du legst Ideen auf ein Board. Ein Team aus KI-Agenten macht daraus funktionierende Features, testet sie und gibt sie dir zurück, samt Schritten zum Ausprobieren. Erledigt ist erst, was du als erledigt erklärst.","AI-gile ist ein selbstgebautes Kanban-Board. Rich hat es mit viel Hilfe genau der Agenten gebaut, die es heute verwaltet. Es ist kostenlos, läuft auf deinem Computer und wird mit Freunden geteilt, nicht verkauft.","Stell dir ein ganz normales Kanban-Board vor, mit Spalten von Backlog bis Erledigt, nur dass die Karten von KI-Agenten bearbeitet werden. Sie melden den Fortschritt, fragen nach, wenn sie hängen, und warten immer auf dein Okay."]},{"n":55,"texts":["AI-gile ist ein Kanban-Board, dessen Team aus KI-Agenten besteht. Jedes Projekt hat einen Lead, der die Arbeit plant, und Helfer, die sie bauen. Ist ein Feature fertig, probiert ein KI-Tester es aus und macht einen Screenshot, dann landet es auf deinem Stapel. Nimm es ab, oder kommentiere, und sie überarbeiten es.","Es fing als Weg eines einzelnen Menschen an, den Überblick über viele KI-Coding-Sitzungen gleichzeitig zu behalten, und wuchs zu einem richtigen Board heran. Es läuft auf deinem Rechner, braucht kein Konto und hat keine Tracker. Für Freunde und Neugierige ist es kostenlos. Es ist auch unfertig, also rechne mit Ecken, Kanten und der einen oder anderen Überraschung.","Hier die ehrliche Version. Die Ideen musst du immer noch selbst haben, und die Ergebnisse musst du immer noch selbst prüfen. Alles dazwischen übernimmt AI-gile: Es hält die Karten in Ordnung, weckt den richtigen Agenten, wenn du kommentierst, zeigt genau, was sich geändert hat, und legt alles auf einen kurzen Stapel für dich."]},{"n":89,"texts":["AI-gile ist ein kostenloses Kanban-Board, das du auf deinem eigenen Computer laufen lässt. Statt Menschen hat jedes Projekt ein Team aus KI-Agenten: einen Lead, der deine Ideen in Karten und einen Plan verwandelt, und Helfer, die die Karten der Priorität nach abarbeiten. Ist etwas gebaut, folgt ein KI-Tester den Testschritten und zeigt dir, was er gesehen hat. Dann wartet es auf einem Stapel mit dem Namen Für dich. Du nimmst es ab, oder du kommentierst und das Team versucht es noch einmal. Nichts landet je ohne dich bei Erledigt.","Ein paar Dinge, die du vielleicht nicht erwartest. Eine Nachtwache hält die Spalte Zu tun gefüllt, während du schläfst, und wählt Karten, für die sie keine Antwort von dir braucht. Ein Token-Zähler zeigt, wie viel die Agenten heute und diese Woche verbraucht haben, und der Kein-Token-Modus sagt ihnen, dass sie nichts mehr ausgeben sollen. Du kannst Freunden schreiben, und private Nachrichten sind Ende-zu-Ende-verschlüsselt. Das Board spricht etwa 120 Sprachen, darunter Niederländisch, Flämisch, Piratisch und Klingonisch. Nichts davon kostet einen Cent, und niemand versucht, es dir zu verkaufen.","AI-gile ist ein kleines, persönliches Projekt, kein Unternehmen. Rich wollte mehrere KI-Coding-Projekte betreuen, ohne jede App zu öffnen, um nachzusehen. Also haben er und die Agenten ein Board dafür gebaut und dann mit dem Board den Rest von ihm selbst. Es ist in der geschlossenen Pre-Alpha, das heisst: Es funktioniert, meistens, für eine Handvoll Freunde. Es gibt keine Preisseite, keinen Newsletter und keinen Wachstumsplan. Klingt es nützlich, kannst du fragen, ob du es ausprobieren darfst, sobald es sich etwas weiter öffnet."]},{"n":144,"texts":["AI-gile ist ein Kanban-Board für einen Menschen und viele KI-Agenten. Es läuft auf deinem eigenen Computer und ist völlig kostenlos. Du legst Projekte an, und jedes Projekt bekommt einen Lead und ein kleines Team. Mit dem Lead chattest du, ein bisschen wie bei Discord, und beschreibst eine Idee; der Lead macht daraus Karten und einen Plan und wartet, bis du auf Los drückst. Das Team arbeitet die Karten der Priorität nach ab, mit einer einfachen Kommandozeile, die für Sprachmodelle gemacht ist. Bevor etwas zu dir zurückkommt, folgt ein KI-Tester den Schritten in einer Kopie der App und hängt einen Screenshot an. Fertige Arbeit landet auf deinem Stapel, samt geänderten Dateien und Diff. Du nimmst sie ab, oder du hinterlässt einen Kommentar, und das Team wacht auf und versucht es erneut. Nur du kannst eine Karte nach Erledigt schieben.","Ein Tag mit AI-gile, grob gesagt. Am Abend hinterlässt du ein paar Kommentare: Dieser Knopf sitzt am falschen Platz, jene Liste sollte sortiert sein, könnten wir einen Dunkelmodus haben? Du gehst ins Bett. Die Agenten lesen die Kommentare, ändern, was gewünscht ist, testen es und geben es dir zurück. Läuft Zu tun leer, füllt die Nachtwache es aus dem Backlog mit Karten auf, die keine Antwort von dir brauchen. Am Morgen wartet ein kurzer Stapel: ein paar Fragen und ein paar Dinge zum Ausprobieren, jeweils mit Schritten, denen ein verschlafener Mensch folgen kann, und einem Screenshot, der zeigt, dass es funktioniert. Du klickst dich durch, nimmst die guten ab und schickst den Rest zurück. Ein Token-Zähler zeigt, was das alles gekostet hat, und der Kein-Token-Modus ist für magere Wochen da. Dann frühstückst du, wobei dir die Agenten noch nicht helfen können.","Zuerst, was AI-gile nicht ist. Es ist kein Start-up, es steht nicht zum Verkauf, und niemand sammelt deine Daten. Es ist ein kostenloses Board, das auf deinem Computer läuft, ohne Konten, ohne Tracker und ohne Cookies. Was es ist: ein ordentlicher Ort, um alle KI-Coding-Projekte auf einmal zu sehen, mit einem Team aus Agenten, das die Karten erledigt, und du triffst die Entscheidungen. Es fasst verwandte Karten zusammen, repariert wirre Titel und achtet darauf, wie schlank der Code bleibt. Es spricht etwa 120 Sprachen, von Niederländisch und Flämisch bis Piratisch und Klingonisch. Freunde können sich privat und verschlüsselt schreiben. Gebaut haben es Rich und sehr viele geduldige Agenten, meistens mit sich selbst. Es ist in der geschlossenen Pre-Alpha und deshalb an manchen Stellen rau. Klingt das nach Spass, frag freundlich, dann kommst du vielleicht früh hinein."]}],"quips":{"1":"Ein Wort. Mutig. Vielleicht zu mutig.","3":"Drei Wörter. Schon ehrlicher als die meisten Produktseiten.","8":"Acht Wörter. Immer noch kürzer als ein Stand-up.","21":"Die Längen sind übrigens Story Points. Natürlich sind sie das.","55":"Fünfundfünfzig Wörter. Zwei Karten wurden fertig, während du das gelesen hast.","144":"Das war die lange Version. Eine 233 gibt es nicht. Die Agenten sind schlafen gegangen."}},"timeline":{"first-idea.name":"Die erste Idee","first-idea.line":"Das allererste Gespräch, noch bevor es Code gab.","first-board.name":"Erstes Board","first-board.line":"Ein Board, das seinen eigenen Bau verfolgt: Karten, Spalten, Drag and Drop, Projekte.","team-roles.name":"Team und Rollen","team-roles.line":"Agentenprofile, Team-Vorlagen, Bereiche und wer was macht.","install.name":"Installation und Releases","install.line":"Ein Zip, das ein Freund installieren kann, mit Selbst-Updates, Kanälen und Rollback.","usage-saver.name":"Verbrauchssparer","usage-saver.line":"Messen, was Läufe kosten, den Code schlank halten, dein Limit schonen.","friends.name":"Freunde und Teilen","friends.line":"Private Nachrichten, ein verschlüsselter Relay, Einladungen, Rollen und geteilte Projekte.","languages.name":"Sprachen","languages.line":"Jeder Bildschirmtext in einer Sprachdatei, zuerst Niederländisch und Flämisch.","ai-tester.name":"KI-Tester","ai-tester.line":"Ein Tester prüft jede Übergabe zuerst und zeigt, was er gesehen hat.","website.name":"Die Website","website.line":"aigile.lol, der Teaser und diese Zeitleiste.","streaming.name":"Chat und Streaming","streaming.line":"Discord, Twitch, OBS, Streamer-Modus, GIFs und Emojis.","no-ai.name":"Edition ohne KI","no-ai.line":"Ein Board für Leute, die ohne KI programmieren, und öffentliche Boards.","night-watch.name":"Nachtwache","night-watch.line":"Ein Wächter und ein Scrum Master halten die Teams bei der Sache, während du schläfst.","p-more.name":"Alles andere","p-more.line":"Kleinere Ideen, die noch auf ihren Auftritt warten.","p-android.name":"Handy und Android","p-android.line":"Dein Board vom Handy aus erreichen, danach eine native Android-App.","p-release.name":"Alpha und weiter","p-release.line":"Geschlossene Alpha, die Live-Seite, dann Beta.","p-languages.name":"Mehr Sprachen","p-languages.line":"Mehr als hundert Sprachen und ein Immersionsmodus für Lernende.","p-engines.name":"Mehr KI-Engines","p-engines.line":"Claude, Codex oder Gemini pro Agent wählen.","p-pro.name":"Profi-Praxis","p-pro.line":"Risiko-Labels, Merge-Gates, Incident-Karten und Leitplanken.","p-self.name":"Auf dich achten","p-self.line":"Müde-Modus, Selbstfürsorge-Erinnerungen und 4:20.","p-servers.name":"Server und Wachstum","p-servers.line":"Globale Servereinstellungen, Rollen und Planung fürs Wachstum.","p-livestream.name":"Streaming-Extras","p-livestream.line":"Twitch-Chat, eigene Emojis und eine öffentliche Live-Ansicht."},"words":{"button":"📖 Fachbegriffe","h":"📖 Begriffe erklärt","intro":"Die Wörter, die dir in AI-gile begegnen, in einfacher Sprache: etwas bauen, es sicher ändern, es für die Leute am Laufen halten, die es nutzen, und als Team mit KI arbeiten.","search":"Wort suchen…","none":"Dazu passt kein Wort.","close":"Schliessen","count":{"one":"{count} Begriff","other":"{count} Begriffe"},"groups":[{"id":"idea","name":"💡 Idee und Entdeckung"},{"id":"plan","name":"🗺️ Die Arbeit planen"},{"id":"agile","name":"🔁 Agile Arbeitsweisen"},{"id":"build","name":"🛠️ Bauen"},{"id":"test","name":"🧪 Testen und Qualität"},{"id":"change","name":"🔀 Sicher ändern"},{"id":"run","name":"🛎️ Einen Service betreiben"},{"id":"sec","name":"🔒 Sicherheit und Datenschutz"},{"id":"ai","name":"🤖 Arbeiten mit KI"},{"id":"money","name":"💰 Geld und Lizenzen"}],"list":[{"id":"discovery","g":"idea","word":"Discovery","text":"Die frühe Phase, in der man herausfindet, welches Problem sich zu lösen lohnt und für wen, bevor irgendetwas gebaut wird.","also":["Discovery-Phase","Entdeckungsphase"]},{"id":"problemstmt","g":"idea","word":"Problembeschreibung","text":"Ein oder zwei Sätze, die sagen, wer ein Problem hat, worin es besteht und warum es wichtig ist, damit alle dasselbe Ziel verfolgen.","also":["Problembeschreibungen","Problem Statement"]},{"id":"user","g":"idea","word":"Nutzer","text":"Ein Mensch, der benutzt, was du baust. Für seine Bedürfnisse wird die Arbeit gemacht.","also":["Nutzerinnen","Anwender","User"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Stakeholder","text":"Alle, denen wichtig ist, wie die Arbeit ausgeht, oder die davon betroffen sind, zum Beispiel die, die dafür zahlen, es nutzen oder unterstützen.","also":["Stakeholder","Beteiligte","Interessengruppen"]},{"id":"persona","g":"idea","word":"Persona","text":"Eine erfundene, aber realistische Person, die für eine Art von Nutzern steht, damit das Team fragen kann: „Findet Sam das einfach?“","also":["Personas"]},{"id":"userresearch","g":"idea","word":"Nutzerforschung","text":"Mit echten Menschen sprechen und ihnen zuschauen, um zu lernen, was sie brauchen, statt zu raten.","also":["User Research","Nutzerinterviews"]},{"id":"journey","g":"idea","word":"User Journey","text":"Die Schritte, die ein Mensch geht, um etwas zu erledigen, von dem Moment, in dem er zum ersten Mal davon hört, bis zum Ende, auch ausserhalb deines Produkts. Wenn du sie aufzeichnest, siehst du, wo er hängen bleibt.","also":["User Journeys","Nutzerreise","Customer Journey"]},{"id":"painpoint","g":"idea","word":"Pain Point","text":"Etwas, das Menschen heute ärgert oder ausbremst. Gute Produkte nehmen Pain Points weg.","also":["Pain Points","Schmerzpunkt","Problemstelle"]},{"id":"assumption","g":"idea","word":"Annahme","text":"Etwas, das du glaubst, aber noch nicht überprüft hast. Wer Annahmen aufschreibt, sieht, was er zuerst testen sollte.","also":["Annahmen"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hypothese","text":"Eine begründete Vermutung, die du überprüfen willst, mit dem, was du erwartest, zum Beispiel „Die Leute melden sich an, wenn der erste Monat gratis ist“.","also":["Hypothesen"]},{"id":"experiment","g":"idea","word":"Experiment","text":"Ein kleiner, geplanter Test, um zu lernen, ob eine Idee funktioniert, bevor man viel darauf setzt.","also":["Experimente"],"noTip":1},{"id":"poc","g":"idea","word":"Proof of Concept (PoC)","text":"Ein schneller, grober Versuch, um zu sehen, ob eine Idee überhaupt funktionieren kann. Meist wird er weggeworfen, sobald du die Antwort hast.","also":["PoC","Proof of Concept","Machbarkeitsnachweis"]},{"id":"prototype","g":"idea","word":"Prototyp","text":"Ein frühes Modell des Produkts, oft anklickbare Bilder, um die Idee an Leuten auszuprobieren, bevor sie richtig gebaut wird.","also":["Prototypen"]},{"id":"wireframe","g":"idea","word":"Wireframe","text":"Eine einfache Skizze eines Bildschirms, die zeigt, wo was hinkommt, ohne Farben oder echte Inhalte.","also":["Wireframes","Drahtgittermodell"]},{"id":"mockup","g":"idea","word":"Mockup","text":"Ein detailliertes Bild davon, wie ein Bildschirm aussehen wird, mit echten Farben und Texten, nur funktioniert noch nichts.","also":["Mockups","Mock-up","Mock-ups","Entwurf"]},{"id":"bizcase","g":"idea","word":"Business Case","text":"Die Gründe für ein Projekt: was es kostet, was es einbringt oder spart und welche Risiken es hat.","also":["Business Cases","Geschäftsfall","Wirtschaftlichkeitsrechnung"]},{"id":"feasibility","g":"idea","word":"Machbarkeit","text":"Ob sich etwas mit der Zeit, dem Geld und den Fähigkeiten, die du hast, wirklich bauen und pflegen lässt.","also":["machbar","Feasibility"]},{"id":"outcome","g":"idea","word":"Wirkung","text":"Die Veränderung, die du für Menschen willst, zum Beispiel weniger verpasste Termine. Sie zählt mehr als die Menge, die du baust.","also":["Wirkungen","Outcome","Outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Ergebnis","text":"Etwas, das das Team herstellt, zum Beispiel eine neue Seite oder ein Bericht. Dass es existiert, heisst nicht automatisch, dass es jemandem hilft.","also":["Ergebnisse","Output","Outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Erfolgskennzahl","text":"Eine Zahl, die dir sagt, ob die Arbeit erreicht hat, wofür sie gedacht war, zum Beispiel mehr Leute, die ihre Bestellung abschliessen.","also":["Erfolgskennzahlen","Success Metric","Erfolgsmetrik"]},{"id":"kpi","g":"idea","word":"Leistungskennzahl (KPI)","text":"Eine wichtige Zahl, die du im Blick behältst, um zu sehen, ob es gut läuft, zum Beispiel Anmeldungen pro Woche.","also":["KPI","KPIs","Key Performance Indicator","Kennzahl"]},{"id":"okr","g":"idea","word":"Ziele und Schlüsselergebnisse (OKRs)","text":"Eine Art, Ziele zu setzen: Das Ziel sagt, was du willst, und ein paar Schlüsselergebnisse sind die Zahlen, die zeigen, dass du es erreicht hast.","also":["OKR","OKRs","Objectives and Key Results"]},{"id":"product","g":"plan","word":"Produkt","text":"Das, was für seine Nutzer gebaut und gepflegt wird, zum Beispiel eine App, eine Website oder ein Werkzeug.","also":["Produkte"],"noTip":1},{"id":"vision","g":"plan","word":"Produktvision","text":"Eine kurze Aussage darüber, wem das Produkt hilft und wohin es langfristig steuert.","also":["Vision","Visionsstatement"]},{"id":"po","g":"plan","word":"Product Owner (PO)","text":"Die Person, die entscheidet, was gebaut wird und in welcher Reihenfolge, damit das Team immer am Wichtigsten arbeitet. In AI-gile bist das du.","also":["PO","Product Owners"]},{"id":"pm","g":"plan","word":"Produktmanager (PM)","text":"Die Person, die sich um die Richtung eines Produkts kümmert: welche Probleme es für wen und warum löst. PM kann auch Projektmanager heissen, schau also genau hin.","also":["Produktmanagerin","Product Manager"]},{"id":"projmgr","g":"plan","word":"Projektleiter","text":"Die Person, die ein Projekt im Zeit- und Kostenrahmen hält und im Blick hat, wer was bis wann macht.","also":["Projektleiterin","Projektmanager","Projektmanagerin"]},{"id":"roadmap","g":"plan","word":"Roadmap","text":"Ein grober Plan, was in den nächsten Monaten kommt, in Reihenfolge. Er zeigt die Richtung, keine genauen Termine, und ändert sich, wenn du dazulernst.","also":["Roadmaps","Fahrplan"]},{"id":"milestone","g":"plan","word":"Meilenstein","text":"Ein Punkt in einem Projekt, der es wert ist, festgehalten zu werden, zum Beispiel „erste Version live“ oder „100 Nutzer“.","also":["Meilensteine"]},{"id":"mvp","g":"plan","word":"Minimum Viable Product (MVP)","text":"Die kleinste Version eines Produkts, die für echte Menschen trotzdem nützlich ist, damit du früh von ihnen lernen kannst.","also":["MVP","MVPs","Minimum Viable Product","minimal brauchbares Produkt"]},{"id":"requirement","g":"plan","word":"Anforderung","text":"Etwas, das das fertige Produkt können oder sein muss.","also":["Anforderungen","Requirement"],"noTip":1},{"id":"scope","g":"plan","word":"Umfang (Scope)","text":"Was zur Arbeit gehört und, genauso wichtig, was nicht.","also":["Scope","im Umfang","ausserhalb des Umfangs","in Scope","out of Scope"]},{"id":"scopecreep","g":"plan","word":"Scope Creep","text":"Wenn nach und nach immer mehr zur Arbeit hinzukommt, ohne dass jemand der zusätzlichen Zeit oder den Kosten zugestimmt hat, sodass sie nie ganz fertig wird.","also":["Feature Creep","schleichende Erweiterung"]},{"id":"feature","g":"plan","word":"Feature","text":"Eine Sache, die das Produkt für Menschen tun kann, zum Beispiel „Passwort zurücksetzen“.","also":["Features","Funktion","Funktionen"],"noTip":1},{"id":"epic","g":"plan","word":"Epic","text":"Ein grosses Stück Arbeit, zu gross für einen Anlauf, deshalb wird es in kleinere Karten aufgeteilt.","also":["Epics"]},{"id":"story","g":"plan","word":"User Story","text":"Ein kleines Stück Arbeit, aus Sicht des Nutzers geschrieben: „Als Kunde möchte ich meinen Warenkorb speichern, damit ich später weitermachen kann.“ Eine solche Story ist der Anfang eines Gesprächs darüber, was gebaut wird.","also":["User Stories","Nutzergeschichte"]},{"id":"ac","g":"plan","word":"Akzeptanzkriterien (AC)","text":"Die Prüfungen, die eine Karte bestehen muss, um als erledigt zu gelten, vor Arbeitsbeginn vereinbart, zum Beispiel „Der Warenkorb ist nach Abmelden und Anmelden noch da“.","also":["AC","Acceptance Criteria"]},{"id":"task","g":"plan","word":"Aufgabe","text":"Eine einzelne Arbeit, die zu erledigen ist, oft ein kleiner Schritt einer grösseren Story.","also":["Aufgaben","Task","Tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Ticket","text":"Ein anderes Wort für eine Karte: ein Stück Arbeit oder eine Anfrage, die von Anfang bis Ende verfolgt wird.","also":["Tickets"]},{"id":"priority","g":"plan","word":"Priorität","text":"Wie wichtig oder dringend etwas im Vergleich zu allem anderen ist, damit die wichtigste Arbeit zuerst drankommt.","also":["Prioritäten"],"noTip":1},{"id":"prioritise","g":"plan","word":"Priorisierung","text":"Arbeit nach Wichtigkeit ordnen. Eine gängige Methode ist MoSCoW: Must have, Should have, Could have, Won’t have (diesmal nicht).","also":["priorisieren","Priorisieren","MoSCoW"]},{"id":"estimate","g":"plan","word":"Schätzung","text":"Eine möglichst gute Vermutung, wie gross ein Stück Arbeit ist oder wie lange es dauert. Es ist eine Schätzung, kein Versprechen.","also":["Schätzungen","Aufwandsschätzung"],"noTip":1},{"id":"storypoints","g":"plan","word":"Story Points","text":"Eine Art, die Grösse von Arbeit zu schätzen, indem man Karten miteinander vergleicht („ungefähr doppelt so gross wie die da“) statt in Stunden. Story Points sind nicht dafür da, Teams zu vergleichen.","also":["Story Point"]},{"id":"tshirt","g":"plan","word":"T-Shirt-Grössen","text":"Die Grösse von Arbeit als S, M, L oder XL schätzen. Schnell und für die frühe Planung gut genug.","also":["T-Shirt-Sizing","T-Shirt-Grössen"]},{"id":"poker","g":"plan","word":"Planning Poker","text":"Ein Schätzspiel: Alle zeigen gleichzeitig eine Grössenkarte, dann erklären die mit der höchsten und der niedrigsten Schätzung, warum.","also":["Scrum Poker"]},{"id":"dependency","g":"plan","word":"Abhängigkeit","text":"Wenn ein Stück Arbeit nicht anfangen oder enden kann, bevor ein anderes fertig ist.","also":["Abhängigkeiten","Dependency"]},{"id":"blocker","g":"plan","word":"Blocker","text":"Alles, was die Arbeit gerade am Weiterkommen hindert, zum Beispiel eine fehlende Antwort oder ein kaputtes Werkzeug.","also":["Blocker","Blockade","Blockaden","Hindernis"]},{"id":"deadline","g":"plan","word":"Deadline","text":"Das Datum, bis zu dem etwas fertig sein muss.","also":["Deadlines","Frist","Abgabetermin"],"noTip":1},{"id":"deliverable","g":"plan","word":"Liefergegenstand","text":"Etwas Greifbares, das die Arbeit hervorbringt und übergibt, zum Beispiel eine funktionierende Seite oder ein Bericht.","also":["Liefergegenstände","Deliverable","Deliverables","Lieferobjekt","Arbeitsergebnis"]},{"id":"forecast","g":"plan","word":"Prognose","text":"Eine Vorhersage dessen, was wahrscheinlich passiert, zum Beispiel wann die Arbeit fertig sein wird, auf Grundlage dessen, was du bisher weisst.","also":["Prognosen","Forecast","Vorhersage"],"noTip":1},{"id":"metric","g":"plan","word":"Kennzahl","text":"Alles, was du misst und über die Zeit verfolgst, zum Beispiel Seitenaufrufe oder wie lange eine Korrektur dauert.","also":["Kennzahlen","Metrik","Metriken"]},{"id":"feedback","g":"plan","word":"Feedback","text":"Was Leute dir über deine Arbeit sagen, Gutes und Schlechtes. Es früh und oft zu bekommen ist der Kern von Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Ideen und Arbeit, die noch nicht eingeplant sind. Daran wird nichts gearbeitet, bis es nach Zu tun wandert."},{"id":"sprint","g":"agile","word":"Sprint","text":"Ein kurzer Arbeitsabschnitt (oft ein bis zwei Wochen) mit einer vereinbarten Menge an Karten, die fertig werden sollen.","also":["Sprints"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Ein kurzes Abstimmen: was jedes Teammitglied gemacht hat, was es als Nächstes tut und was es aufhält.","also":["Standup","Stand-ups","Daily"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Ein Board mit Spalten (Zu tun, In Arbeit, Erledigt), in dem Karten von links nach rechts wandern, während die Arbeit läuft."},{"id":"wip","g":"agile","word":"WIP-Limit","text":"Work in Progress: die Höchstzahl an Karten in einer Spalte, damit das Team Dinge abschliesst, bevor es Neues anfängt.","also":["WIP"]},{"id":"dod","g":"agile","word":"Definition of Done","text":"Die kurze Checkliste des Teams, was „fertig“ heisst, etwa getestet und erklärt, bevor eine Karte an dich geht. Ihr Zwilling, die Definition of Ready, sagt, wann eine Karte klar genug ist, um anzufangen.","also":["Definition of Ready","DoD","DoR"]},{"id":"retro","g":"agile","word":"Retro","text":"Ein Rückblick darauf, wie das Team arbeitet, um sich auf eine Sache zu einigen, die besser werden soll. In AI-gile schlägt eine Retro eine Änderung an der Arbeitsweise des Teams vor, und du sagst Go oder Noch nicht.","also":["Retros","Retrospektive","Retrospektiven"]},{"id":"swarm","g":"agile","word":"Schwarm","text":"Alle Mann an Deck: Jedes Team lässt andere Arbeit liegen und hilft bei einem dringenden Projekt, bis es gelöst ist. Andere Projekte warten so lange.","also":["Schwärmen","Swarm","Swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"Derjenige, der die Arbeit am Fliessen hält: entdeckt hängende Karten, stupst die Teams an und erinnert dich daran, was wartet. In AI-gile macht das der Lead Scrum Master über alle Projekte hinweg.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"Eine Arbeitsweise in kleinen Schritten: ein bisschen bauen, oft echte Ergebnisse zeigen, aus dem lernen, was Leute sagen, und den Plan unterwegs ändern, statt alles im Voraus zu planen.","also":["Agile Entwicklung","agile Arbeitsweisen","agil"]},{"id":"manifesto","g":"agile","word":"Agiles Manifest","text":"Eine kurze Erklärung, die 2001 von Softwareentwicklern geschrieben wurde. Sie stellt Menschen, funktionierende Ergebnisse, enge Zusammenarbeit mit Kunden und den Umgang mit Veränderung über schwere Pläne und Papierkram.","also":["Agile Manifesto","Manifest für agile Softwareentwicklung"]},{"id":"waterfall","g":"agile","word":"Wasserfall","text":"Die ältere Arbeitsweise: erst alles planen, dann alles bauen, dann alles testen, eine Phase nach der anderen. Späte Änderungen sind schwierig und teuer.","also":["Wasserfallmodell","Waterfall"]},{"id":"iteration","g":"agile","word":"Iteration","text":"Eine Runde, in der man etwas baut, prüft und verbessert. Agile Arbeit ist eine Kette solcher Runden, und ein Sprint ist eine davon.","also":["Iterationen"]},{"id":"increment","g":"agile","word":"Inkrement","text":"Ein neues, funktionierendes Stück, das in einem Sprint oder einer Arbeitsrunde zum Produkt hinzukommt und zu dem passt, was schon da war.","also":["Inkremente","Increment"]},{"id":"scrum","g":"agile","word":"Scrum","text":"Eine beliebte agile Arbeitsweise: Ein kleines Team arbeitet in kurzen Sprints auf ein Ziel hin, mit festen Rollen und ein paar regelmässigen Treffen zum Planen, Prüfen und Verbessern."},{"id":"scrumteam","g":"agile","word":"Scrum-Team","text":"Die kleine Gruppe, die in Scrum die Arbeit macht: ein Product Owner, ein Scrum Master und die Entwickler.","also":["Scrum-Teams"]},{"id":"ceremonies","g":"agile","word":"Scrum-Events","text":"Die regelmässigen Treffen in Scrum: Sprint Planning, das Daily Scrum, das Sprint Review und die Retro. Viele nennen sie Zeremonien.","also":["Zeremonien","Scrum-Zeremonien","Scrum Events"]},{"id":"sprintplan","g":"agile","word":"Sprint Planning","text":"Das Treffen zu Beginn eines Sprints, in dem das Team klärt, warum der Sprint wichtig ist, welche Karten es übernimmt und wie es anfängt.","also":["Planungsmeeting","Sprint-Planung"]},{"id":"sprintgoal","g":"agile","word":"Sprintziel","text":"Ein Satz, der sagt, wofür ein Sprint da ist. Kleine Aufgaben dürfen sich unterwegs ändern, solange das Ziel erreicht wird.","also":["Sprintziele","Sprint Goal"]},{"id":"sprintbacklog","g":"agile","word":"Sprint Backlog","text":"Die Karten, die für den aktuellen Sprint ausgewählt wurden, mit dem Plan des Teams, sie zu erledigen.","also":["Sprint Backlogs"]},{"id":"productbacklog","g":"agile","word":"Product Backlog","text":"Die vollständige, geordnete Liste von allem, was für das Produkt gebaut werden könnte, das Wichtigste ganz oben. Sie ändert sich ständig, wenn du dazulernst.","also":["Product Backlogs"]},{"id":"productgoal","g":"agile","word":"Produktziel","text":"Das grössere Ergebnis, auf das das Produkt hinarbeitet und das dem Team hilft, zu entscheiden, was als Nächstes dran ist.","also":["Produktziele","Product Goal"]},{"id":"refinement","g":"agile","word":"Backlog Refinement","text":"Das Backlog regelmässig durchgehen, um Karten aufzuräumen, aufzuteilen, zu ordnen und mit Details zu versehen, damit sie bereit zum Anpacken sind. Auch Backlog Grooming genannt.","also":["Backlog Grooming","Refinement","Backlog-Pflege"]},{"id":"sprintreview","g":"agile","word":"Sprint Review","text":"Ein Treffen am Ende eines Sprints, in dem das Team zeigt, was es geschafft hat, und hört, was die Leute davon halten, um zu entscheiden, was als Nächstes kommt.","also":["Sprint Reviews"]},{"id":"demo","g":"agile","word":"Demo","text":"Fertige Arbeit live und in Aktion denen zeigen, die darum gebeten haben.","also":["Demos","Vorführung"],"noTip":1},{"id":"timebox","g":"agile","word":"Timebox","text":"Eine feste Zeitspanne für etwas. Wenn sie abläuft, hörst du auf, auch wenn nicht alles fertig ist.","also":["Timeboxing","Timeboxes","zeitlich begrenzt"]},{"id":"velocity","g":"agile","word":"Velocity","text":"Wie viel Arbeit ein Team normalerweise in einem Sprint schafft, damit man planen kann, wie viel es sich beim nächsten Mal vornimmt. Sie sagt nicht, wie hart die Leute arbeiten.","also":["Teamgeschwindigkeit","Team Velocity"]},{"id":"capacity","g":"agile","word":"Kapazität","text":"Wie viel Arbeit das Team in einem Zeitraum übernehmen kann, nach Abzug von Urlaub und anderen Aufgaben.","noTip":1},{"id":"burndown","g":"agile","word":"Burndown-Chart","text":"Ein Diagramm der Restarbeit in einem Sprint, die Tag für Tag sinkt. Bleibt die Linie flach, hängt etwas fest.","also":["Burndown","Burn-down-Chart"]},{"id":"burnup","g":"agile","word":"Burnup-Chart","text":"Ein Diagramm der fertigen Arbeit, die mit der Zeit steigt, neben der geplanten Gesamtmenge, sodass du siehst, wann du ankommst.","also":["Burnup","Burn-up-Chart"]},{"id":"kanbanboard","g":"agile","word":"Kanban-Board","text":"Das Board selbst: eine Spalte für jede Phase der Arbeit, durch die die Karten wandern.","also":["Kanban-Boards"]},{"id":"pullsys","g":"agile","word":"Pull-System","text":"Eine Arbeitsweise, bei der neue Arbeit erst anfängt, wenn jemand Platz hat, sie zu übernehmen, statt jemandem, der schon voll ist, noch etwas aufzuladen.","also":["Pull-Prinzip","pullbasiert"]},{"id":"flow","g":"agile","word":"Flow","text":"Wie reibungslos die Arbeit über das Board läuft. Guter Flow heisst, die Karten bewegen sich weiter, statt sich zu stauen.","also":["Arbeitsfluss","Fluss der Arbeit"],"noTip":1},{"id":"leadtime","g":"agile","word":"Lead Time","text":"Wie lange es dauert von dem Moment, in dem jemand um etwas bittet, bis es fertig ist.","also":["Durchlaufzeit","Lead Times"]},{"id":"cycletime","g":"agile","word":"Cycle Time","text":"Wie lange eine Karte braucht, von dem Moment, in dem die Arbeit wirklich beginnt, bis zur Fertigstellung.","also":["Zykluszeit","Cycle Times"]},{"id":"throughput","g":"agile","word":"Durchsatz","text":"Wie viele Karten pro Woche oder in einer anderen festen Zeit fertig werden.","also":["Throughput","Durchsatzrate"]},{"id":"bottleneck","g":"agile","word":"Engpass","text":"Die eine Stelle, an der sich Arbeit staut und alles dahinter bremst, wie der enge Hals einer Flasche.","also":["Engpässe","Bottleneck","Flaschenhals"]},{"id":"swimlane","g":"agile","word":"Swimlane","text":"Eine Zeile quer über das Board, die Karten einer Art zusammenfasst, zum Beispiel dringende Arbeit oder die Karten eines Teams.","also":["Swimlanes","Schwimmbahn"]},{"id":"lean","g":"agile","word":"Lean","text":"Eine Arbeitsweise, die Verschwendung (alles, was dem Kunden nicht hilft) streicht und die Arbeit im Fluss hält."},{"id":"waste","g":"agile","word":"Verschwendung","text":"In Lean alles, was Mühe kostet, aber dem Kunden nicht hilft, zum Beispiel Warten, Nacharbeit oder Dinge zu bauen, die niemand benutzt.","noTip":1},{"id":"kaizen","g":"agile","word":"Kontinuierliche Verbesserung","text":"Durch kleine, regelmässige Änderungen ständig ein bisschen besser werden und dann prüfen, ob sie geholfen haben. Retros sind eine Möglichkeit dafür. Auch Kaizen genannt.","also":["Kaizen","ständige Verbesserung","KVP","Continuous Improvement"]},{"id":"selforg","g":"agile","word":"Selbstorganisiertes Team","text":"Ein Team, das selbst entscheidet, wie es die Arbeit erledigt, statt Schritt für Schritt Anweisungen zu bekommen.","also":["selbstorganisiert","selbstorganisierend","selbstverwaltetes Team"]},{"id":"crossfunc","g":"agile","word":"Funktionsübergreifendes Team","text":"Ein Team, das alle Fähigkeiten hat, die es braucht, um die Arbeit selbst abzuschliessen, zum Beispiel Design, Bauen und Testen.","also":["funktionsübergreifend","cross-funktional"]},{"id":"spike","g":"agile","word":"Spike","text":"Eine kurze, zeitlich begrenzte Recherche, die eine Frage beantwortet, bevor man sich auf die eigentliche Arbeit festlegt.","also":["Spikes"]},{"id":"rework","g":"agile","word":"Nacharbeit","text":"Arbeit noch einmal machen, weil sie beim ersten Mal nicht richtig war.","also":["nacharbeiten","Rework"]},{"id":"safe","g":"agile","word":"Skaliertes Agile (SAFe)","text":"Wege, Agile über viele Teams in einer grossen Organisation hinweg einzusetzen. SAFe (das Scaled Agile Framework) ist ein bekanntes Beispiel.","also":["skaliertes Agile","Scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"Der Ordner des Projekts mit Code und der vollständigen Commit-Historie, meist auch auf GitHub gespeichert.","also":["Repository"]},{"id":"branch","g":"build","word":"Branch","text":"Eine getrennte Arbeitslinie im Code, damit man Änderungen machen kann, ohne die Hauptversion anzufassen.","also":["Branches","Zweig"]},{"id":"commit","g":"build","word":"Commit","text":"Ein gespeicherter Schnappschuss des Codes, mit einer kurzen Notiz, was sich geändert hat. Zu einem kannst du jederzeit zurück.","also":["Commits"]},{"id":"push","g":"build","word":"Push","text":"Gespeicherte Schnappschüsse (Commits) von diesem Rechner nach GitHub schicken, damit sie gesichert und geteilt sind."},{"id":"merge","g":"build","word":"Merge","text":"Die Änderungen eines Branches zurück in die Hauptversion zusammenführen."},{"id":"pr","g":"build","word":"Pull Request","text":"Darum bitten, dass die Änderungen eines Branches geprüft und in die Hauptversion gemergt werden.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactoring","text":"Den Code aufräumen, ohne zu ändern, was er tut: kleinere Dateien, klarere Namen, weniger Wiederholung."},{"id":"bug","g":"build","word":"Bug","text":"Etwas, das nicht so funktioniert, wie es soll.","also":["Bugs","Fehler"]},{"id":"peerreview","g":"build","word":"Peer-Review","text":"Ein zweites Paar Augen: Eine andere KI prüft die Arbeit jeder Karte, bevor sie bei dir ankommt, damit weniger Fehler durchrutschen.","also":["Code-Review","Code Review","Review"]},{"id":"code","g":"build","word":"Code","text":"Die geschriebenen Anweisungen, die einem Computer sagen, was er tun soll. Auch Quellcode genannt.","also":["Quellcode"],"noTip":1},{"id":"proglang","g":"build","word":"Programmiersprache","text":"Eine Sprache zum Schreiben von Code, zum Beispiel JavaScript, Python oder Java. Verschiedene eignen sich für verschiedene Aufgaben.","also":["Programmiersprachen"]},{"id":"developer","g":"build","word":"Entwickler (Dev)","text":"Jemand, der Code schreibt und ändert. Auch Programmierer oder Softwareentwickler genannt.","also":["Entwicklerin","Developer","Dev","Programmierer","Programmiererin","Softwareentwickler"]},{"id":"software","g":"build","word":"Software","text":"Programme, die auf Computern und Handys laufen, im Gegensatz zu den Geräten selbst (der Hardware).","noTip":1},{"id":"app","g":"build","word":"App","text":"Kurz für Anwendung: ein Programm, mit dem Leute etwas erledigen, auf dem Handy, dem Computer oder im Webbrowser.","also":["Apps","Anwendung","Anwendungen","Applikation"],"noTip":1},{"id":"webapp","g":"build","word":"Web-App","text":"Eine App, die im Webbrowser läuft, sodass nichts installiert werden muss.","also":["Web-Apps","Webanwendung","Webapplikation"]},{"id":"frontend","g":"build","word":"Frontend","text":"Der Teil einer App, den du siehst und anklickst: die Bildschirme, Knöpfe und Texte, oft im Browser.","also":["Front-End","Frontend","Oberfläche"]},{"id":"backend","g":"build","word":"Backend","text":"Der Teil einer App hinter den Kulissen, der die Daten aufbewahrt und die Arbeit erledigt, wenn du etwas anklickst, zum Beispiel dein Passwort prüft.","also":["Back-End","Backend"]},{"id":"fullstack","g":"build","word":"Full Stack","text":"Sowohl am Frontend als auch am Backend arbeiten.","also":["Full-Stack","Fullstack"]},{"id":"ui","g":"build","word":"Benutzeroberfläche (UI)","text":"Was ein Mensch auf dem Bildschirm sieht und benutzt: Aufbau, Knöpfe, Menüs und Texte.","also":["UI","User Interface","Oberfläche"]},{"id":"ux","g":"build","word":"Nutzererlebnis (UX)","text":"Wie es sich anfühlt, etwas zu benutzen: einfach, klar und angenehm oder verwirrend und langsam.","also":["UX","User Experience","Nutzererfahrung"]},{"id":"accessibility","g":"build","word":"Barrierefreiheit (a11y)","text":"Dinge so machen, dass alle sie nutzen können, auch Menschen, die schlecht sehen, keine Maus benutzen können oder einen Screenreader verwenden.","also":["a11y","Accessibility","barrierefrei"]},{"id":"responsive","g":"build","word":"Responsive Design","text":"Seiten so gestalten, dass sie auf jeder Bildschirmgrösse passen und gut funktionieren, vom Handy bis zum grossen Monitor.","also":["responsiv"]},{"id":"designsys","g":"build","word":"Designsystem","text":"Ein gemeinsames Set aus Farben, Schriften, Knöpfen und Regeln, damit jeder Bildschirm gleich aussieht und sich gleich verhält.","also":["Designsysteme","Design System"]},{"id":"architecture","g":"build","word":"Architektur","text":"Der grundlegende Aufbau eines Systems: was die Hauptteile sind und wie sie miteinander sprechen."},{"id":"database","g":"build","word":"Datenbank (DB)","text":"Ein geordneter Speicher für Informationen, wie eine sehr leistungsfähige Tabelle, die die App lesen und ändern kann.","also":["Datenbanken","DB","Database"]},{"id":"schema","g":"build","word":"Datenbankschema","text":"Der Aufbau einer Datenbank: welche Tabellen mit Informationen es gibt und was in jede gehört.","also":["Schema"]},{"id":"sql","g":"build","word":"SQL","text":"Kurz für „Structured Query Language“: die Sprache, mit der man viele Datenbanken nach Informationen fragt oder sie ändert.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Daten","text":"Informationen, die ein Computer speichert, zum Beispiel Namen, Bestellungen oder Einstellungen.","also":["Datensatz","Datensätze","Data"],"noTip":1},{"id":"server","g":"build","word":"Server","text":"Ein Computer, der immer an ist und Anfragen von anderen Computern beantwortet, zum Beispiel eine Webseite schickt, wenn du sie besuchst.","also":["Servers"]},{"id":"client","g":"build","word":"Client","text":"Die Seite, die mit einem Server spricht und etwas anfragt, meist dein Browser oder deine App. Im Geschäftsleben heisst es auch einfach Kunde.","also":["Clients","Kunde"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Kurz für „Application Programming Interface“ (Programmierschnittstelle): eine feste Speisekarte von Anfragen, die ein Programm an ein anderes stellen kann, etwa wenn man einen Wetterdienst nach der heutigen Vorhersage fragt.","also":["APIs","Programmierschnittstelle","Application Programming Interface"]},{"id":"endpoint","g":"build","word":"Endpunkt","text":"Ein Eintrag auf der Speisekarte einer API: eine Webadresse, die ein Programm aufrufen kann, um etwas abzuholen oder zu senden.","also":["Endpunkte","Endpoint","Endpoints"]},{"id":"integration","g":"build","word":"Integration","text":"Zwei Systeme verbinden, damit sie zusammenarbeiten, etwa wenn dein Shop Bestellungen an deine Buchhaltungssoftware schickt.","also":["Integrationen","Anbindung"]},{"id":"webhook","g":"build","word":"Webhook","text":"Eine Nachricht, die ein System von selbst an ein anderes schickt, sobald etwas passiert, etwa „Zahlung eingegangen“.","also":["Webhooks"]},{"id":"library","g":"build","word":"Bibliothek","text":"Fertiger Code, den jemand anderes geschrieben hat und den du wiederverwenden kannst, statt ihn selbst zu schreiben.","also":["Bibliotheken","Library","Libraries"],"noTip":1},{"id":"framework","g":"build","word":"Framework","text":"Eine fertige Struktur zum Bauen einer App, die vieles davon festlegt, wie der Code aufgebaut ist, wie der Rohbau eines Hauses, den du ausbaust.","also":["Frameworks"]},{"id":"sdk","g":"build","word":"Software-Entwicklungskit (SDK)","text":"Ein Werkzeugkasten aus Tools, Code und Beispielen, um Software für eine Plattform oder einen Dienst zu bauen.","also":["SDK","SDKs","Software Development Kit"]},{"id":"softdep","g":"build","word":"Software-Abhängigkeit","text":"Eine Bibliothek oder ein Werkzeug, das dein Code zum Funktionieren braucht. Solche Abhängigkeiten aktuell zu halten ist wichtig für die Sicherheit.","also":["Software-Abhängigkeiten","Abhängigkeiten","Dependencies"]},{"id":"package","g":"build","word":"Paket","text":"Ein Bündel fertigen Codes, das du installieren und in einem Projekt benutzen kannst.","also":["Pakete","Package","Packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Paketmanager","text":"Ein Werkzeug, das die Pakete holt und aktualisiert, von denen dein Code abhängt. npm ist ein weit verbreiteter.","also":["Paketmanager","Package Manager","npm"]},{"id":"git","g":"build","word":"Git","text":"Das am weitesten verbreitete Werkzeug, um die Geschichte von Codeänderungen festzuhalten, in Commits und Branches."},{"id":"github","g":"build","word":"GitHub","text":"Eine Website, die Git-Repos online aufbewahrt, damit Teams Code teilen, Änderungen prüfen und Arbeit verfolgen können."},{"id":"vcs","g":"build","word":"Versionskontrolle","text":"Eine vollständige Geschichte jeder Änderung an den Dateien aufbewahren, damit du siehst, wer was geändert hat, und bei Bedarf zurückgehen kannst. Git macht das.","also":["Quellcodeverwaltung","Versionsverwaltung","Version Control"]},{"id":"clone","g":"build","word":"Klonen","text":"Eine eigene vollständige Kopie eines Repos samt Geschichte auf deinem Computer anlegen.","also":["Clone","klonen","geklont"]},{"id":"pull","g":"build","word":"Pull","text":"Die neuesten Commits von der gemeinsamen Kopie (zum Beispiel GitHub) auf deinen Computer holen. Das Gegenteil von Push.","also":["git pull","Pullen"],"noTip":1},{"id":"mainbranch","g":"build","word":"Hauptbranch","text":"Die offizielle Version des Codes, von der alle ausgehen, oft main oder master genannt.","also":["Main-Branch","Master-Branch","Main Branch"]},{"id":"conflict","g":"build","word":"Merge-Konflikt","text":"Wenn zwei Änderungen dieselben Zeilen auf verschiedene Weise anfassen, sodass der Computer sie nicht zusammenführen kann und ein Mensch entscheiden muss.","also":["Merge-Konflikte","Merge Conflict"]},{"id":"diff","g":"build","word":"Diff","text":"Eine Ansicht, die genau zeigt, was sich zwischen zwei Versionen geändert hat: hinzugefügte und entfernte Zeilen.","also":["Diffs","Unterschied","Änderungsansicht"]},{"id":"fork","g":"build","word":"Fork","text":"Deine eigene Kopie des Repos von jemand anderem, die du ändern kannst, ohne das Original zu verändern.","also":["Forks","forken","geforkt"]},{"id":"script","g":"build","word":"Skript","text":"Ein kurzes Programm, das eine Aufgabe von selbst erledigt, zum Beispiel Dateien aufräumen oder die App starten.","also":["Skripte","Script","Scripts"],"noTip":1},{"id":"build","g":"build","word":"Build","text":"Den Code in etwas Lauffähiges verwandeln, oder das lauffähige Ergebnis selbst.","also":["Builds"],"noTip":1},{"id":"compile","g":"build","word":"Kompilieren","text":"Von Menschen geschriebenen Code in eine Form übersetzen, die der Computer direkt ausführen kann.","also":["kompiliert","Compiler","Compile","Kompilierung"]},{"id":"cli","g":"build","word":"Kommandozeile (CLI)","text":"Ein Textfenster, in das du Anweisungen für den Computer tippst, statt zu klicken. Auch Terminal genannt.","also":["Kommandozeile","Befehlszeile","CLI","Terminal"]},{"id":"config","g":"build","word":"Konfiguration (Config)","text":"Die Einstellungen, die steuern, wie sich Software verhält, getrennt vom Code aufbewahrt, damit sie leicht zu ändern sind.","also":["Config","Konfiguration","Einstellungen"],"noTip":1},{"id":"envvar","g":"build","word":"Umgebungsvariable","text":"Eine Einstellung, die einem Programm beim Start mitgegeben wird, oft für Adressen oder Passwörter, damit sie nicht im Code stehen.","also":["Umgebungsvariablen","Env-Variable","Environment Variable"]},{"id":"debugging","g":"build","word":"Debugging","text":"Herausfinden, warum etwas nicht funktioniert, und es beheben.","also":["debuggen","Debug","Fehlersuche"]},{"id":"pairing","g":"build","word":"Pair Programming","text":"Zwei Menschen (oder ein Mensch und eine KI) arbeiten gemeinsam am selben Code, einer tippt, einer prüft.","also":["Pairing","Paarprogrammierung"]},{"id":"docs","g":"build","word":"Dokumentation (Docs)","text":"Schriftliche Erklärungen, wie etwas funktioniert oder wie man es benutzt.","also":["Docs","Dokumentation"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"Die erste Datei, die man in einem Repo lesen sollte: was das Projekt ist und wie man es zum Laufen bringt.","also":["READMEs","Lies-mich-Datei"]},{"id":"legacy","g":"build","word":"Altsystem","text":"Ein älteres System, das noch im Einsatz ist und sich schwer ändern lässt, oft weil nur noch wenige es verstehen.","also":["Altsysteme","Legacy-System","Legacy-Systeme","Legacy-Code"]},{"id":"techdebt","g":"build","word":"Technische Schulden","text":"Abkürzungen, die jetzt Zeit sparen, aber spätere Änderungen langsamer machen, wie ein Kredit, auf den Zinsen auflaufen. Refactoring zahlt sie ab.","also":["Tech Debt","technische Schuld"]},{"id":"test","g":"test","word":"Test","text":"Ein fertiges Stück Arbeit ausprobieren, um zu prüfen, ob es tut, was verlangt wurde, bevor du es akzeptierst.","also":["Tests"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Kurz für Qualitätssicherung: die automatischen Prüfungen, die laufen, bevor etwas live geht. Ist QA rot, ist etwas fehlgeschlagen, und es kann erst live gehen, wenn das behoben ist.","also":["Qualitätssicherung","Qualitätsprüfung","Qualitätsprüfungen"]},{"id":"testpile","g":"test","word":"Teststapel","text":"Die fertigen Karten, die darauf warten, dass du sie ausprobierst, eine nach der anderen. Nimm eine an oder schick sie mit einer Notiz zurück, und die nächste kommt.","also":["Teststapeln"]},{"id":"autotest","g":"test","word":"Automatisierter Test","text":"Eine Prüfung, die der Computer bei jeder Codeänderung von selbst ausführt, um Fehler früh zu finden.","also":["automatisierte Tests","automatische Tests","Autotest"]},{"id":"manualtest","g":"test","word":"Manueller Test","text":"Ein Mensch probiert die Arbeit von Hand aus, um zu sehen, ob sie sich so verhält, wie sie soll.","also":["manuelle Tests","manuelles Testen","Handtest"]},{"id":"unittest","g":"test","word":"Unit-Test","text":"Eine kleine automatische Prüfung eines winzigen Stücks Code für sich allein.","also":["Unit-Tests","Unittest","Komponententest"]},{"id":"integtest","g":"test","word":"Integrationstest","text":"Eine Prüfung, ob mehrere Teile richtig zusammenarbeiten, nicht nur einzeln.","also":["Integrationstests","Integration Test"]},{"id":"endtoend","g":"test","word":"End-to-End-Test (E2E)","text":"Ein Test, der sich wie ein echter Nutzer von Anfang bis Ende verhält, etwa anmelden, kaufen und bezahlen.","also":["E2E","End-to-End-Tests","Ende-zu-Ende-Test"]},{"id":"uat","g":"test","word":"Abnahmetest (UAT)","text":"Die Leute, die die Arbeit in Auftrag gegeben haben, probieren sie selbst aus und sagen, ob sie tut, was sie brauchen. Der Teststapel von AI-gile ist seine Version davon.","also":["UAT","User Acceptance Testing","Akzeptanztest"]},{"id":"regression","g":"test","word":"Regression","text":"Etwas, das früher funktioniert hat und nach einer Änderung kaputtging. Regressionstests prüfen, dass das Alte noch funktioniert.","also":["Regressionen","Regressionstest","Regressionstests","Regressionstesten"]},{"id":"smoke","g":"test","word":"Smoke-Test","text":"Eine sehr schnelle Prüfung, ob die wichtigsten Dinge überhaupt funktionieren, zum Beispiel direkt nachdem eine Änderung live gegangen ist. Schlägt sie fehl: anhalten und nachsehen.","also":["Smoke-Tests","Rauchtest"]},{"id":"exploratory","g":"test","word":"Explorativer Test","text":"Das Produkt frei ausprobieren und auf verschiedene Weisen anstupsen, um Probleme zu finden, die geplante Prüfungen übersehen würden.","also":["explorative Tests","exploratives Testen","Exploratory Testing"]},{"id":"testcase","g":"test","word":"Testfall","text":"Ein aufgeschriebenes Szenario zum Ausprobieren: die Schritte und was passieren soll.","also":["Testfälle","Test Case"]},{"id":"coverage","g":"test","word":"Testabdeckung","text":"Wie viel vom Code von automatischen Tests geprüft wird. Mehr ist meist sicherer, aber hohe Abdeckung allein beweist nicht, dass es gut funktioniert.","also":["Abdeckung","Code Coverage"]},{"id":"testdata","g":"test","word":"Testdaten","text":"Ausgedachte Beispielinformationen, die beim Testen benutzt werden, damit keine privaten Angaben echter Menschen offenliegen.","also":["Test Fixtures","Testdaten"]},{"id":"edgecase","g":"test","word":"Randfall","text":"Eine ungewöhnliche Situation an den Grenzen, etwa ein leeres Formular oder ein Name mit Apostroph, wo oft etwas kaputtgeht.","also":["Randfälle","Edge Case","Grenzfall"]},{"id":"happypath","g":"test","word":"Happy Path","text":"Der normale Weg, auf dem alles gut läuft. Gutes Testen probiert auch die Wege, auf denen etwas schiefgeht."},{"id":"perftest","g":"test","word":"Performancetest","text":"Prüfen, wie schnell etwas ist und wie gut es unter Belastung zurechtkommt.","also":["Performancetests","Leistungstest","Leistungstests","Performance Testing"]},{"id":"loadtest","g":"test","word":"Lasttest","text":"Prüfen, wie ein System zurechtkommt, wenn viele Leute es gleichzeitig benutzen.","also":["Lasttests","Load Testing"]},{"id":"sectest","g":"test","word":"Sicherheitstest","text":"Nach Schwachstellen suchen, durch die jemand ein System missbrauchen oder sehen könnte, was er nicht sehen soll.","also":["Sicherheitstests","Security Testing","Penetrationstest"]},{"id":"accesstest","g":"test","word":"Barrierefreiheitstest","text":"Prüfen, ob Menschen mit unterschiedlichen Fähigkeiten das Produkt nutzen können, auch mit Screenreader oder nur mit der Tastatur.","also":["Barrierefreiheitstests","Accessibility Testing"]},{"id":"linting","g":"test","word":"Linting","text":"Eine automatische Prüfung, die wahrscheinliche Fehler und unordentlichen Stil im Code findet, wie eine Rechtschreibprüfung für Programme.","also":["Linter","Lint"]},{"id":"static","g":"test","word":"Statische Analyse","text":"Code automatisch auf Probleme durchsehen lassen, ohne ihn auszuführen.","also":["statische Codeanalyse","Static Analysis"]},{"id":"flaky","g":"test","word":"Flaky Test","text":"Ein Test, der manchmal besteht und manchmal durchfällt, ohne erkennbaren Grund, sodass man ihm nicht ganz trauen kann.","also":["Flaky Tests","instabiler Test","wackeliger Test"]},{"id":"repro","g":"test","word":"Reproduzieren (Repro)","text":"Einen Bug absichtlich noch einmal auftreten lassen, indem man dieselben Schritte befolgt, damit man ihn untersuchen und beheben kann. Diese Schritte aufzuschreiben ist der nützlichste Teil eines Bugreports.","also":["Repro","reproduzieren","Schritte zum Reproduzieren"]},{"id":"severity","g":"test","word":"Schweregrad","text":"Wie schlimm die Auswirkung eines Problems ist, von einem kleinen Ärgernis bis hin zum Stillstand von allem.","also":["Severity","Schweregradstufe","Fehlerschwere"]},{"id":"deploy","g":"change","word":"Deploy","text":"Eine neue Version live schalten, zum Beispiel auf einem Server, auf dem Leute sie nutzen."},{"id":"release","g":"change","word":"Release","text":"Ein benanntes Paket fertiger Arbeit, das gemeinsam live geht, mit kurzen Notizen dazu, was sich geändert hat. 🚀 Releases schreibt die Notizen aus den erledigten Karten.","also":["Releases","Version","Versionen"]},{"id":"rollback","g":"change","word":"Rollback","text":"Zurück zur letzten Version, die funktioniert hat, wenn eine neue Ärger macht. In AI-gile entsteht daraus eine Checkliste mit den Rückgängig-Schritten, die bei jeder Änderung notiert sind.","also":["Rollbacks","zurückrollen","zurückgerollt","zurücksetzen"]},{"id":"live","g":"change","word":"Live","text":"Die echte Version, die Leute benutzen, im Gegensatz zu einer Kopie zum Ausprobieren. Entwickler nennen das auch Produktion.","also":["Produktion","Produktivsystem"],"noTip":1},{"id":"change","g":"change","word":"Änderung","text":"Eine geplante Änderung an etwas, auf das sich Leute verlassen, vorher aufgeschrieben: was, warum, das Risiko, wann und wie man sie rückgängig macht. Starte eine mit 🔀 Änderung beantragen.","also":["Änderungen","Änderungsantrag","Änderungsanträge","Change"],"noTip":1},{"id":"risk","g":"change","word":"Risiko","text":"Etwas, das schiefgehen könnte, bewertet danach, wie wahrscheinlich und wie schlimm es wäre. ⚠️ Risiken hält sie in einer Liste, höchste Bewertung zuerst, jedes mit einem Datum zum erneuten Ansehen.","also":["Risiken","Risikoliste","Risikoregister"]},{"id":"chgwin","g":"change","word":"Änderungsfenster","text":"Die Zeiten, in denen Änderungen live gehen dürfen, etwa ein ruhiger Dienstagabend. Ausserhalb eines Fensters lässt sich eine Änderungskarte nicht abschliessen, ausser im Notfall.","also":["Wartungsfenster"]},{"id":"gonogo","g":"change","word":"Go / No-Go","text":"Eine kurze Abstimmung, kurz bevor eine Änderung live geht: Jede Person, die zustimmen muss, sagt Go oder No-Go. Es geht nur weiter, wenn alle einverstanden sind.","also":["Go/No-Go","Go-No-Go"]},{"id":"approval","g":"change","word":"Freigabe","text":"Auf ein Ja warten, bevor die Arbeit beginnt. Eine Karte, die ein Freund anlegt, oder eine Änderung wartet in ✅ Freigaben, bis du sie freigibst oder ablehnst.","also":["Freigaben","Genehmigung","Genehmigungen"]},{"id":"quiettime","g":"change","word":"Ruhezeit","text":"Eine Zeitspanne, etwa ein Stream, eine Demo oder die Nacht, in der nichts live geht. Die Teams arbeiten und testen weiter, aber live gehen wartet, bis sie vorbei ist. Anderswo heisst das Change Freeze.","also":["Ruhezeiten","Change Freeze","Änderungsstopp"]},{"id":"devops","g":"change","word":"DevOps","text":"Eine Arbeitsweise, bei der die Leute, die Software bauen, und die Leute, die sie betreiben, als ein Team arbeiten, mit viel Automatisierung, sodass Änderungen oft und sicher live gehen."},{"id":"cicd","g":"change","word":"CI/CD (kontinuierliche Integration und Auslieferung)","text":"Die Änderungen aller werden oft in die Hauptversion zusammengeführt und jedes Mal automatisch geprüft (kontinuierliche Integration), sodass die Software immer auf Knopfdruck live gehen kann (kontinuierliche Auslieferung).","also":["CI/CD","CI","CD","Continuous Integration","Continuous Delivery"]},{"id":"contdeploy","g":"change","word":"Continuous Deployment","text":"Einen Schritt weiter als Continuous Delivery: Jede Änderung, die die Prüfungen besteht, geht von selbst live, ohne Knopf, den man drücken muss.","also":["kontinuierliches Deployment","Continuous Deployments"]},{"id":"pipeline","g":"change","word":"Pipeline","text":"Die automatische Folge von Schritten, die eine Änderung auf dem Weg in den Livebetrieb durchläuft, etwa bauen, testen, dann ausliefern.","also":["Pipelines"]},{"id":"environment","g":"change","word":"Umgebung","text":"Eine getrennte Kopie des Systems für einen Zweck, zum Beispiel eine zum Bauen, eine zum Testen und die Live-Umgebung.","also":["Umgebungen","Environment","Environments"],"noTip":1},{"id":"devenv","g":"change","word":"Entwicklungsumgebung","text":"Die Kopie, in der ein Entwickler arbeitet, oft auf dem eigenen Computer, wo es niemandem schadet, wenn etwas kaputtgeht.","also":["Dev-Umgebung","Dev Environment"]},{"id":"testenv","g":"change","word":"Testumgebung","text":"Eine getrennte Kopie des Systems, die nur zum Testen dient, damit der echte Dienst unberührt bleibt.","also":["Testumgebungen","Test Environment"]},{"id":"staging","g":"change","word":"Staging","text":"Eine letzte Kopie, die genauso eingerichtet ist wie die Live-Umgebung, für eine Abschlussprüfung, bevor eine Änderung live geht.","also":["Staging-Umgebung","Staging Environment"]},{"id":"artifact","g":"change","word":"Build-Artefakt","text":"Die Datei oder das Bündel, das ein Build erzeugt, bereit zum Speichern, Prüfen oder Livestellen.","also":["Build-Artefakte","Artefakt","Build Artifact"]},{"id":"hotfix","g":"change","word":"Hotfix","text":"Eine dringende Korrektur, die ausserhalb des normalen Plans schnell live gestellt wird, weil etwas Wichtiges kaputt ist.","also":["Hotfixes"]},{"id":"patch","g":"change","word":"Patch","text":"Ein kleines Update, das einen Bug behebt oder eine Sicherheitslücke schliesst. Sicherheitspatches schnell einzuspielen ist wichtig.","also":["Patches","Sicherheitspatch","Sicherheitspatches","Security Patch"]},{"id":"version","g":"change","word":"Versionsnummer","text":"Eine Bezeichnung wie 2.4.1, die sagt, welchen Stand du hast. Oft ändert sich die erste Zahl bei grossen Änderungen und die letzte bei kleinen Korrekturen.","also":["Versionsnummern","Semantic Versioning","semantische Versionierung"]},{"id":"relnotes","g":"change","word":"Release Notes","text":"Eine kurze, einfache Liste dessen, was sich in einem Release geändert hat, für die Leute, die es benutzen, mit Korrekturen und bekannten Einschränkungen. Auch Changelog genannt.","also":["Changelog","Änderungsprotokoll","Versionshinweise"]},{"id":"flag","g":"change","word":"Feature-Flag","text":"Ein Ein-Aus-Schalter für eine Funktion, damit neue Arbeit versteckt live gehen und ohne neues Release ein- (oder wieder aus-)geschaltet werden kann.","also":["Feature-Flags","Feature Flag","Feature-Toggle","Feature Toggle"]},{"id":"rollfwd","g":"change","word":"Roll Forward","text":"Ein schlechtes Release beheben, indem man schnell eine neue, korrigierte Version herausbringt, statt zur alten zurückzugehen.","also":["vorwärts korrigieren","Roll-forward","Fix Forward"]},{"id":"canary","g":"change","word":"Canary-Release","text":"Eine Änderung zuerst für eine kleine Gruppe live stellen und erst für alle, wenn alles gut aussieht. Benannt nach den Kanarienvögeln, die Bergleute als Frühwarnung mit unter Tage nahmen.","also":["Canary-Releases","Canary","Canary Release"]},{"id":"bluegreen","g":"change","word":"Blue-Green-Deployment","text":"Zwei Kopien des Live-Systems vorhalten und alle auf einmal auf die neue umschalten, sodass man sofort zurückschalten kann, wenn es schiefgeht.","also":["Blue-Green","Blue Green Deployment","Blau-Grün-Deployment"]},{"id":"zerodown","g":"change","word":"Deployment ohne Ausfallzeit","text":"Eine neue Version live stellen, ohne dass der Dienst für seine Nutzer jemals stehen bleibt.","also":["Zero Downtime","Zero-Downtime","unterbrechungsfreies Deployment"]},{"id":"chgenable","g":"change","word":"Change Enablement","text":"Änderungen zum Erfolg verhelfen: das Risiko abwägen, die richtige Freigabe einholen und einen guten Zeitpunkt wählen. Auch Change Management genannt.","also":["Change Management","Änderungsmanagement"]},{"id":"cab","g":"change","word":"Change Advisory Board (CAB)","text":"Eine Gruppe, die wichtige Änderungen prüft und entscheidet, ob und wann sie umgesetzt werden dürfen.","also":["CAB","Änderungsbeirat"]},{"id":"stdchange","g":"change","word":"Standardänderung","text":"Eine risikoarme Änderung, die jedes Mal auf dieselbe bewährte Weise gemacht wird und deshalb im Voraus freigegeben ist.","also":["Standardänderungen","Standard Change"]},{"id":"normchange","g":"change","word":"Normale Änderung","text":"Eine Änderung, die geprüft und freigegeben werden muss, bevor sie umgesetzt wird.","also":["normale Änderungen","Normal Change"]},{"id":"emergchange","g":"change","word":"Notfalländerung","text":"Eine Änderung, die sofort passieren muss, um ernste Probleme zu beheben oder zu verhindern, mit einer entsprechend schnelleren Freigabe.","also":["Notfalländerungen","Emergency Change"]},{"id":"automation","g":"change","word":"Automatisierung","text":"Den Computer eine wiederkehrende Arbeit von selbst erledigen lassen, damit sie schneller geht und jedes Mal gleich gemacht wird.","also":["automatisiert","Automation"],"noTip":1},{"id":"infra","g":"change","word":"Infrastruktur","text":"Die Maschinen, Netzwerke und Dienste, auf denen Software läuft.","also":["Infra"]},{"id":"iac","g":"change","word":"Infrastruktur als Code (IaC)","text":"Server und Einstellungen in Dateien beschreiben, die zusammen mit dem Code liegen, damit sie jedes Mal genau gleich neu aufgebaut werden können.","also":["IaC","Infrastructure as Code"]},{"id":"cloud","g":"change","word":"Cloud","text":"Computer, Speicher und Dienste bei einem grossen Anbieter über das Internet mieten, statt die Maschinen selbst zu besitzen.","also":["die Cloud","Cloud Computing","Cloud-Computing"]},{"id":"provider","g":"change","word":"Cloud-Anbieter","text":"Ein Unternehmen, das Rechenleistung über das Internet vermietet, etwa Amazon Web Services (AWS), Microsoft Azure oder Google Cloud.","also":["Cloud Provider","Cloud-Provider"]},{"id":"hosting","g":"change","word":"Hosting","text":"Wo deine App oder Website liegt und läuft, damit Leute sie erreichen können, meist bei einer Firma gemietet.","also":["gehostet","Webhosting"]},{"id":"domain","g":"change","word":"Domainname","text":"Die Webadresse, die Leute eintippen, zum Beispiel example.com. Du mietest sie jahresweise, deshalb muss sie verlängert werden.","also":["Domainnamen","Domain","Webadresse"]},{"id":"dns","g":"change","word":"DNS","text":"Kurz für „Domain Name System“: das Adressbuch des Internets, das einen Namen wie example.com in die Adresse des richtigen Computers umwandelt.","also":["Domain Name System"]},{"id":"container","g":"change","word":"Container","text":"Ein versiegeltes Paket mit einer App und allem, was sie braucht, damit sie auf jedem Computer gleich läuft. Docker ist das bekannteste Werkzeug.","also":["Container","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Virtuelle Maschine (VM)","text":"Ein simulierter Computer, der in einem echten läuft, sodass eine grosse Maschine wie viele wirken kann.","also":["VM","VMs","virtuelle Maschinen"]},{"id":"serverless","g":"change","word":"Serverless","text":"Code ausführen, ohne sich selbst um Server zu kümmern: Der Anbieter führt ihn bei Bedarf aus, und du zahlst für das, was du nutzt."},{"id":"lb","g":"change","word":"Load Balancer","text":"Etwas, das Besucher auf mehrere Server verteilt, damit kein einzelner überlastet wird.","also":["Load Balancers","Lastverteiler"]},{"id":"cache","g":"change","word":"Cache","text":"Ein praktischer Speicher für zuletzt abgerufene Ergebnisse, griffbereit gehalten, damit dasselbe nicht noch einmal geholt oder berechnet werden muss. Ihn zu leeren kann Seiten reparieren, die veraltet aussehen.","also":["Caches","Caching","zwischengespeichert"]},{"id":"cdn","g":"change","word":"Content Delivery Network (CDN)","text":"Ein weltweites Netz von Servern, die Kopien deiner Seiten und Bilder nahe bei deinen Besuchern bereithalten, damit sie schnell laden.","also":["CDN"]},{"id":"migration","g":"change","word":"Migration","text":"Daten oder Systeme von einer alten Lösung in eine neue umziehen oder sorgfältig ändern, wie eine Datenbank aufgebaut ist.","also":["Migrationen","Datenbankmigration"]},{"id":"service","g":"run","word":"Service","text":"Etwas, das du gebaut hast und auf das sich Leute verlassen, etwa eine Website oder eine App, und das gepflegt wird, damit es weiter funktioniert. Hake „Dieses Projekt ist ein Service“ an und sag, was er bietet, wer ihn nutzt und wer Bereitschaft hat.","also":["Services","Dienst","Dienste"]},{"id":"uptimepct","g":"run","word":"Uptime","text":"Der Anteil der Zeit, in dem ein Dienst funktioniert, meist in Prozent. Bei 99,9 % sind im Monat trotzdem etwa 43 Minuten Ausfall erlaubt.","also":["Verfügbarkeit in Prozent","Uptime-Prozentsatz"]},{"id":"uptime","g":"run","word":"Uptime-Check","text":"Eine automatische Prüfung alle paar Minuten, ob dein Service noch antwortet. Schlägt sie mehrmals hintereinander fehl, legt AI-gile von selbst eine Vorfallkarte an.","also":["Uptime","Uptime-Checks","Verfügbarkeitsprüfung"]},{"id":"statuspage","g":"run","word":"Statusseite","text":"Eine öffentliche Seite, die zeigt, ob ein Service funktioniert (grün, orange oder rot), mit dem neuesten Stand, damit die Nutzer nachsehen können, statt zu fragen.","also":["Statusseiten","Status-Seite"]},{"id":"desk","g":"run","word":"Service-Desk","text":"Hier kommen Fragen und Meldungen der Leute an, die deinen Service nutzen. AI-gile sortiert jede davon als Anfrage, Vorfall oder Idee ein und sagt Bescheid, wenn sie nach etwas aussieht, das schon gemeldet wurde.","also":["Service-Desks","Helpdesk","Help-Desk","Schreibtisch"]},{"id":"svcrequest","g":"run","word":"Service-Anfrage","text":"Jemand bittet um etwas Alltägliches, etwa ein neues Konto oder ein bisschen Hilfe, statt zu melden, dass etwas kaputt ist. Sie wartet, bis sie dran ist; ein Vorfall geht vor.","also":["Service-Anfragen","Service Request","Service Requests"]},{"id":"incident","g":"run","word":"Vorfall","text":"Etwas, das gerade jetzt für die Nutzer kaputt ist, zum Beispiel wenn die Website nicht erreichbar ist. Eine 🔥 Vorfallkarte überspringt die Warteschlange: Es wieder zum Laufen zu bringen hat Vorrang.","also":["Vorfälle","Incident","Incidents","Störung"]},{"id":"major","g":"run","word":"Major-Vorfall","text":"Ein grosser Vorfall: viele Leute betroffen oder Geld oder Daten in Gefahr. Ein Knopf setzt alle Teams darauf an (Schwarm), weckt, wer Bereitschaft hat, und bittet alle 30 Minuten um ein Status-Update.","also":["Major-Vorfälle","Major Incident","schwerer Vorfall"]},{"id":"oncall","g":"run","word":"Bereitschaft","text":"Derjenige sein, der reagiert, wenn etwas kaputtgeht, auch nachts. Jeder Service hat ein Teammitglied in Bereitschaft, das bei seinen Vorfällen als Erstes geweckt wird.","also":["Rufbereitschaft","On-Call","Bereitschaftsdienst"]},{"id":"replyby","g":"run","word":"Antwortfrist","text":"Wie lange eine Karte auf eine erste Antwort warten darf, zum Beispiel eine Stunde bei einem Vorfall. Danach bekommt sie eine rote Uhr, damit nichts still vergessen wird. Heisst auch Reaktionszeit.","also":["Antwortfristen","Reaktionszeit","Reaktionszeiten"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"Ein kurzer Rückblick nach einem Vorfall: was passiert ist, was geholfen hat und was sich ändern soll, ohne jemandem die Schuld zu geben. Ohne ihn lässt sich ein Vorfall nicht schliessen.","also":["Post-mortems","Postmortem","Nachbetrachtung"]},{"id":"problem","g":"run","word":"Problem","text":"Die versteckte Ursache hinter einem oder mehreren Vorfällen. Eine 🧩 Problemkarte bündelt Vorfälle, die immer wiederkommen, damit die Ursache gefunden und endgültig behoben wird.","also":["Probleme"],"noTip":1},{"id":"rootcause","g":"run","word":"Grundursache","text":"Der eigentliche Grund, warum etwas kaputtgegangen ist, nicht nur das, was man schiefgehen sah. Behebe die Grundursache, und der Vorfall kommt nicht wieder.","also":["Grundursachen","Ursache","Root Cause"]},{"id":"workaround","g":"run","word":"Workaround","text":"Ein Weg, die Dinge am Laufen zu halten, bis die echte Lösung fertig ist, etwa etwas neu zu starten, wenn es hängt. Er steht auf der Problemkarte, damit niemand ihn neu herausfinden muss.","also":["Workarounds","Umgehungslösung","Behelfslösung"]},{"id":"knownerror","g":"run","word":"Bekannter Fehler","text":"Ein Problem, dessen Ursache verstanden ist und für das es einen Workaround gibt, das aber noch nicht behoben ist. 🧩 Bekannte Fehler listet sie auf, damit alle den Workaround nutzen, statt wieder zu suchen.","also":["Bekannte Fehler","Known Error","Known Errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Schritt-für-Schritt-Anleitung, um eine bekannte Art von Störung zu beheben, damit es jedes Mal gleich und schnell gemacht wird. Nach einem grossen Vorfall kann das Team eins vorschlagen, das du absegnest.","also":["Runbooks","Betriebshandbuch"]},{"id":"ci","g":"run","word":"Konfigurationselement","text":"Eine Sache, von der dein Service abhängt, etwa ein Server, eine Domain, ein Zertifikat, ein Schlüssel oder ein Anbieter. 🗂️ Konfigurationselemente listet sie pro Service auf, damit du siehst, was ein Vorfall betrifft und was erneuert oder gesichert werden muss.","also":["Konfigurationselemente","Configuration Item","Configuration Items","CI"]},{"id":"expiry","g":"run","word":"Ablaufdatum","text":"AI-gile behält Daten im Blick, etwa wann ein Zertifikat oder eine Domain ausläuft. 30 Tage vorher legt es eine Karte zum Erneuern an, damit nichts überraschend aufhört zu funktionieren.","also":["Ablaufdaten","Ablauf","Ablaufüberwachung"]},{"id":"backup","g":"run","word":"Sicherung","text":"Eine gespeicherte Kopie deiner Daten von früher, auf die du zurückgreifen kannst, wenn etwas verloren geht oder beschädigt wird. AI-gile macht jeden Tag eine Sicherung deiner Boards.","also":["Sicherungen","Backup","Backups","Datensicherung"]},{"id":"restore","g":"run","word":"Wiederherstellen","text":"Daten aus einer Sicherung zurückholen. Eine Sicherung zählt erst richtig, wenn du weisst, dass sie sich wiederherstellen lässt, deshalb lohnt es sich, das ab und zu auszuprobieren.","also":["wiederhergestellt","Wiederherstellung","Restore"]},{"id":"svcreview","g":"run","word":"Service-Rückblick","text":"Ein Blick zurück auf einen Monat eines Service: eröffnete und behobene Vorfälle, wie schnell Leute eine Antwort bekamen, Verfügbarkeit und verbrauchte Tokens. Der Monatliche Rückblick zeigt das für jeden Service.","also":["Service-Rückblicke","Monatlicher Rückblick","Monatsrückblick","Monatsrückblicke"]},{"id":"accessreview","g":"run","word":"Zugriffsprüfung","text":"Alle 90 Tage prüfen, wer noch hineinkommt: Freigabelinks, Rollen von Freunden und gespeicherte Geheimnisse. Du behältst oder entfernst jedes einzeln, damit alte Zugänge nicht herumliegen.","also":["Zugriffsprüfungen","Access Review"]},{"id":"improvements","g":"run","word":"Verbesserungsliste","text":"Alles, worin das Team besser werden will, an einem Ort: Retro-Vorschläge, Massnahmen aus Nachbesprechungen und Problembehebungen, jeweils mit Status. Du findest sie unter 📈 Verbesserungen.","also":["Verbesserungslisten","Verbesserungen"]},{"id":"tokencap","g":"run","word":"Token-Limit","text":"Eine monatliche Grenze für die Tokens, die die Agenten eines Service verbrauchen dürfen. Bei 80 % bekommst du eine Warnung; bei 100 % wartet ihre Hintergrundarbeit bis zum nächsten Monat oder bis du das Limit erhöhst.","also":["Token-Limits","Token Cap"]},{"id":"svcmgmt","g":"run","word":"Servicemanagement","text":"Alles, was dazugehört, einen Dienst Tag für Tag nützlich und funktionsfähig für die Leute zu halten, die sich darauf verlassen.","also":["Service Management","einen Service betreiben"]},{"id":"itil","g":"run","word":"ITIL","text":"Ein weit verbreiteter Leitfaden für gutes Servicemanagement, der Dinge wie Störungen, Probleme und Änderungen behandelt. Der Name stand einmal für IT Infrastructure Library."},{"id":"itsm","g":"run","word":"IT-Servicemanagement (ITSM)","text":"Technik als Dienstleistung für Menschen betreiben, mit klaren Wegen für Anfragen, Störungen, Änderungen und Verbesserungen.","also":["ITSM","IT Service Management"]},{"id":"managed","g":"run","word":"Managed Service","text":"Ein Dienst, den jemand anderes für dich betreibt und pflegt, gemäss einer Vereinbarung darüber, wie gut er funktionieren muss.","also":["Managed Services","verwalteter Dienst"]},{"id":"svcowner","g":"run","word":"Service Owner","text":"Die Person, die für einen Dienst als Ganzes geradesteht: wie gut er funktioniert, was er kostet und wie er besser wird.","also":["Service Owners","Serviceverantwortlicher"]},{"id":"sla","g":"run","word":"Service Level Agreement (SLA)","text":"Ein schriftliches Versprechen an Kunden, wie gut ein Dienst funktionieren wird, etwa „99,9 % der Zeit erreichbar“ oder „innerhalb einer Stunde beantwortet“, oft mit Geld zurück, wenn es nicht eingehalten wird.","also":["SLA","SLAs","Service-Level-Vereinbarung"]},{"id":"slo","g":"run","word":"Service Level Objective (SLO)","text":"Das eigene Ziel des Teams, wie gut ein Dienst über einen Zeitraum funktionieren soll, meist etwas strenger als das SLA gesetzt, um auf der sicheren Seite zu sein.","also":["SLO","SLOs","Service-Level-Ziel"]},{"id":"sli","g":"run","word":"Service Level Indicator (SLI)","text":"Die tatsächliche Messung, die du mit einem Ziel vergleichst, zum Beispiel der Anteil der Besuche, die einwandfrei geladen haben.","also":["SLI","SLIs","Service-Level-Indikator"]},{"id":"availability","g":"run","word":"Verfügbarkeit","text":"Ob Leute einen Dienst nutzen können, wenn sie ihn brauchen, oft als Uptime gemessen.","also":["Hochverfügbarkeit","Availability"]},{"id":"downtime","g":"run","word":"Downtime","text":"Zeit, in der ein Dienst nicht funktioniert oder abgeschaltet ist, geplant oder nicht.","also":["Ausfallzeit","Down Time"]},{"id":"errorbudget","g":"run","word":"Error Budget","text":"Die kleine Menge an Ausfall, die dein Verlässlichkeitsziel erlaubt. Solange etwas übrig ist, kannst du bei Änderungen Risiken eingehen; ist es aufgebraucht, gehst du langsamer vor.","also":["Error Budgets","Fehlerbudget"]},{"id":"outage","g":"run","word":"Ausfall","text":"Eine Zeit, in der ein Dienst für seine Nutzer nicht erreichbar oder schwer gestört ist.","also":["Ausfälle","Outage","Outages"]},{"id":"degraded","g":"run","word":"Eingeschränkt","text":"Läuft, aber schlecht: langsam, oder einige Teile funktionieren nicht.","also":["eingeschränkter Betrieb","Degraded","Degraded Service"]},{"id":"monitoring","g":"run","word":"Monitoring","text":"Einen Dienst die ganze Zeit automatisch beobachten, damit Probleme auffallen, am besten bevor die Nutzer sie bemerken.","also":["überwacht","Überwachung"]},{"id":"observability","g":"run","word":"Observability","text":"Wie gut du von aussen erkennen kannst, was im Inneren eines Systems vor sich geht, anhand seiner Logs, Zahlen und Traces.","also":["o11y","Beobachtbarkeit"]},{"id":"log","g":"run","word":"Log","text":"Ein laufendes Tagebuch, das ein Programm darüber führt, was es tut, und das hilft herauszufinden, was schiefgelaufen ist.","also":["Logs","Logging","Protokoll"],"noTip":1},{"id":"trace","g":"run","word":"Trace","text":"Eine Aufzeichnung, wie eine einzelne Anfrage Schritt für Schritt durch die verschiedenen Teile eines Systems wandert und wo sie langsam wurde.","also":["Traces","Tracing","Ablaufverfolgung"]},{"id":"latency","g":"run","word":"Latenz","text":"Wie lange etwas braucht, um zu antworten, etwa die Wartezeit zwischen dem Klick und dem Erscheinen der Seite.","also":["Latency"]},{"id":"alert","g":"run","word":"Alarm","text":"Eine automatische Nachricht, dass etwas Aufmerksamkeit braucht, zum Beispiel dass die Website nicht antwortet.","also":["Alarme","Alert","Alerts","Alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Alarmmüdigkeit","text":"Wenn es so viele Alarme gibt, dass die Leute anfangen, sie zu ignorieren, auch die wichtigen.","also":["Alert Fatigue","Alarmflut"]},{"id":"dashboard","g":"run","word":"Dashboard","text":"Ein Bildschirm, der die wichtigsten Zahlen und Zustände auf einen Blick zeigt.","also":["Dashboards","Übersichtstafel"],"noTip":1},{"id":"paging","g":"run","word":"Paging","text":"Die Bereitschaftsperson bei einem Problem dringend anrufen oder aus dem Schlaf holen.","also":["Pagen","angepiept","alarmiert"]},{"id":"escalation","g":"run","word":"Eskalation","text":"Jemanden mit mehr Können oder Befugnis hinzuziehen, wenn ein Problem auf der aktuellen Ebene nicht oder nicht schnell genug gelöst werden kann.","also":["eskalieren","eskaliert","Escalation"]},{"id":"triage","g":"run","word":"Triage","text":"Eingehende Probleme schnell danach sortieren, wie dringend und wichtig sie sind, damit das Schlimmste zuerst drankommt.","also":["triagieren","Triagierung"]},{"id":"impact","g":"run","word":"Auswirkung","text":"Wie stark etwas Menschen betrifft: wie viele und wie schlimm.","noTip":1},{"id":"urgency","g":"run","word":"Dringlichkeit","text":"Wie schnell sich jemand um etwas kümmern muss. Auswirkung und Dringlichkeit zusammen bestimmen die Priorität.","noTip":1},{"id":"plevels","g":"run","word":"Prioritätsstufen (P1, P2 …)","text":"Bezeichnungen dafür, wie dringend ein Problem ist. P1 ist das schwerwiegendste und verlangt sofortiges Handeln.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Ticket-Warteschlange","text":"Die Liste der Anfragen und Störungen, die darauf warten, aufgegriffen zu werden.","also":["Ticket-Warteschlangen","Ticket Queue"]},{"id":"tiers","g":"run","word":"First- und Second-Level-Support","text":"Support-Ebenen: Der First-Level-Support nimmt den Anruf entgegen und löst einfache Dinge; der Second-Level-Support hat tieferes Fachwissen für schwierigere Fälle. Auch Tier 1 und Tier 2 genannt.","also":["1st Level","2nd Level","First-Level-Support","Tier 1","Tier 2"]},{"id":"ic","g":"run","word":"Incident Commander","text":"Die eine Person, die die Reaktion auf eine Störung leitet, damit alle wissen, wer entscheidet und wer was macht.","also":["Incident Commanders","Einsatzleiter"]},{"id":"responsetime","g":"run","word":"Reaktionszeit","text":"Wie lange es dauert, bis jemand eine Anfrage oder Störung zum ersten Mal aufgreift.","also":["Reaktionszeiten","Response Time"]},{"id":"resolution","g":"run","word":"Lösungszeit","text":"Wie lange es dauert, eine Anfrage oder Störung ganz zu klären, von der Meldung bis zur Behebung.","also":["Lösungszeiten","Resolution Time","Zeit bis zur Lösung"]},{"id":"mttr","g":"run","word":"Mittlere Wiederherstellungszeit (MTTR)","text":"Wie lange es im Durchschnitt dauert, einen Dienst nach einem Ausfall wieder zum Laufen zu bringen. MTTR kann leicht Unterschiedliches bedeuten, sag also, was du misst.","also":["MTTR","Mean Time to Recover","Mean Time to Restore"]},{"id":"mtbf","g":"run","word":"Mittlere Zeit zwischen Ausfällen (MTBF)","text":"Wie lange ein Dienst im Durchschnitt läuft, bevor etwas kaputtgeht.","also":["MTBF","Mean Time Between Failures"]},{"id":"cmdb","g":"run","word":"Konfigurationsdatenbank (CMDB)","text":"Die Liste aller deiner Konfigurationselemente und wie sie zusammenhängen, damit du siehst, was wovon abhängt.","also":["CMDB","Configuration Management Database"]},{"id":"asset","g":"run","word":"Asset","text":"Alles Wertvolle, das du besitzt oder bezahlst, um den Dienst zu betreiben, zum Beispiel ein Laptop, eine Softwarelizenz oder eine Domain.","also":["Assets","Vermögenswert","Betriebsmittel"],"noTip":1},{"id":"capplan","g":"run","word":"Kapazitätsplanung","text":"Dafür sorgen, dass genug Rechenleistung, Speicher und Personal für das da ist, was kommt.","also":["Kapazitätsplan","Capacity Planning"]},{"id":"scaling","g":"run","word":"Skalierung","text":"Mit mehr Nutzern zurechtkommen, indem man einer Maschine mehr Leistung gibt (vertikal skalieren) oder weitere Maschinen hinzufügt (horizontal skalieren).","also":["Skalieren","vertikal skalieren","horizontal skalieren","Scale up","Scale out"]},{"id":"bcp","g":"run","word":"Betriebskontinuität","text":"Pläne, um das Wichtige am Laufen zu halten, wenn etwas Grosses schiefgeht, etwa wenn ein Büro, ein wichtiger Lieferant oder die Computer ausfallen.","also":["Business Continuity","Notfallplan","Business-Continuity-Plan"]},{"id":"dr","g":"run","word":"Notfallwiederherstellung (DR)","text":"Der Plan und die Werkzeuge, um einen Dienst nach einem schweren Vorfall wiederherzustellen, etwa nach dem Verlust eines ganzen Rechenzentrums.","also":["Disaster Recovery","Katastrophenwiederherstellung"]},{"id":"rto","g":"run","word":"Wiederherstellungszeitziel (RTO)","text":"Die längste Zeit, die ein Dienst nach einer Katastrophe ausfallen darf, bevor er wieder funktionieren muss.","also":["RTO","Recovery Time Objective"]},{"id":"rpo","g":"run","word":"Wiederherstellungspunktziel (RPO)","text":"Wie viele der neuesten Daten du höchstens verlieren darfst, in Zeit gemessen. Ein RPO von einer Stunde bedeutet Backups mindestens jede Stunde.","also":["RPO","Recovery Point Objective"]},{"id":"redundancy","g":"run","word":"Redundanz","text":"Ersatz bereithalten, etwa einen zweiten Server, damit ein Ausfall den Dienst nicht stoppt.","also":["Ausfallsicherheit"]},{"id":"failover","g":"run","word":"Failover","text":"Von selbst auf ein Ersatzsystem umschalten, wenn das übliche ausfällt.","also":["Fail-over","Ausfallumschaltung"]},{"id":"spof","g":"run","word":"Single Point of Failure","text":"Ein einzelnes Teil, das alles lahmlegt, wenn es kaputtgeht, weil es keinen Ersatz gibt.","also":["Single Points of Failure","SPOF","einzelne Schwachstelle"]},{"id":"maintwin","g":"run","word":"Wartungsfenster","text":"Eine geplante Zeit, in der ein Dienst für Wartungsarbeiten angehalten oder langsam sein darf und die den Nutzern vorher angekündigt wird.","also":["Wartungsfenster","geplante Wartung","Maintenance Window"]},{"id":"handover","g":"run","word":"Übergabe","text":"Arbeit, Wissen und Verantwortung an eine andere Person oder ein anderes Team weitergeben, damit nichts verloren geht.","also":["Übergaben","Handover","übergeben"]},{"id":"kb","g":"run","word":"Wissensdatenbank","text":"Eine Sammlung von Hilfeartikeln und Antworten, für Nutzer und für das Team.","also":["Wissensdatenbanken","Knowledge Base","Wissensbasis"]},{"id":"csat","g":"run","word":"Kundenzufriedenheit (CSAT)","text":"Eine Bewertung der Nutzer, wie zufrieden sie waren, oft nach dem Schliessen einer Anfrage abgefragt.","also":["CSAT","Customer Satisfaction"]},{"id":"supplier","g":"run","word":"Lieferant","text":"Eine externe Firma, auf die du dich verlässt, zum Beispiel dein Hosting-Anbieter. Auch Vendor oder Drittanbieter genannt.","also":["Lieferanten","Anbieter","Vendor","Vendors","Drittanbieter"],"noTip":1},{"id":"retire","g":"run","word":"Service-Abschaltung","text":"Einen Dienst sicher und endgültig abschalten: seine Nutzer informieren, sich um seine Daten und Zugänge kümmern und die laufenden Kosten stoppen.","also":["Service abschalten","Ausserbetriebnahme"]},{"id":"eol","g":"run","word":"End of Life (EOL)","text":"Wenn ein Produkt vom Hersteller keine Updates oder keinen Support mehr bekommt und deshalb ersetzt werden sollte.","also":["EOL","End-of-Life","Lebensende"]},{"id":"cybersec","g":"sec","word":"Cybersicherheit","text":"Systeme und Daten davor schützen, dass jemand einbricht, sie stiehlt oder beschädigt.","also":["Cybersecurity","Cyber Security","IT-Sicherheit"]},{"id":"authn","g":"sec","word":"Authentifizierung","text":"Prüfen, wer jemand ist, meist mit einem Passwort oder einem Code. Oft zu authn abgekürzt.","also":["authn","Authentication","Anmeldung"]},{"id":"authz","g":"sec","word":"Autorisierung","text":"Prüfen, was jemand tun darf, sobald du weisst, wer er ist. Oft zu authz abgekürzt.","also":["authz","Authorization","Berechtigungsprüfung"]},{"id":"mfa","g":"sec","word":"Mehrfaktor-Authentifizierung (MFA)","text":"Mit zwei oder mehr Nachweisen anmelden, zum Beispiel einem Passwort plus einem Code auf dem Handy. Auch Zwei-Faktor (2FA) genannt.","also":["MFA","2FA","Zwei-Faktor","Zwei-Faktor-Authentifizierung"]},{"id":"sso","g":"sec","word":"Single Sign-on (SSO)","text":"Sich einmal anmelden, um in viele Systeme zu kommen, etwa mit dem Firmenkonto überall.","also":["SSO","Einmalanmeldung"]},{"id":"pwmgr","g":"sec","word":"Passwortmanager","text":"Eine App, die starke Passwörter erzeugt und sie für dich merkt.","also":["Passwort-Manager","Passwortmanager"]},{"id":"secret","g":"sec","word":"Geheimnis (Secret)","text":"Ein Passwort, ein Schlüssel oder ein anderer privater Code, mit dem ein Programm sich irgendwo Zugang verschafft. Ein Secret darf nie weitergegeben oder in den Code geschrieben werden.","also":["Secrets","Geheimnisse"],"noTip":1},{"id":"apikey","g":"sec","word":"API-Schlüssel","text":"Ein geheimer Code, mit dem ein Programm die API eines anderen Dienstes nutzen darf und der zeigt, wer sie nutzt (und bezahlt).","also":["API-Schlüssel","API Key","API Keys"]},{"id":"accesstoken","g":"sec","word":"Zugriffstoken","text":"Ein befristeter Ausweis, der beweist, dass ein Programm hinein darf, damit es nicht jedes Mal dein Passwort braucht. Nicht dasselbe wie ein KI-Token.","also":["Access Token","Access Tokens","Zugriffstokens"]},{"id":"encryption","g":"sec","word":"Verschlüsselung","text":"Informationen so durcheinanderbringen, dass nur jemand mit dem richtigen Schlüssel sie lesen kann.","also":["verschlüsselt","verschlüsseln","Encryption"]},{"id":"https","g":"sec","word":"HTTPS","text":"Die sichere Art, wie Webseiten übertragen werden, zu erkennen am Schloss im Browser, damit niemand dazwischen sie lesen oder ändern kann."},{"id":"cert","g":"sec","word":"SSL/TLS-Zertifikat","text":"Ein digitaler Ausweis, mit dem eine Website beweist, wer sie ist, und HTTPS nutzen kann. Er läuft ab und muss deshalb erneuert werden.","also":["TLS-Zertifikat","SSL-Zertifikat","Zertifikat","Zertifikate"]},{"id":"permissions","g":"sec","word":"Berechtigungen","text":"Die Regeln, wer was sehen oder ändern darf.","also":["Berechtigung","Rechte","Zugriffsrechte"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Minimale Rechte","text":"Jeder Person und jedem Programm nur den Zugang geben, den sie wirklich brauchen, und nur so lange, wie sie ihn brauchen.","also":["Least Privilege","Prinzip der minimalen Rechte","Prinzip der geringsten Rechte"]},{"id":"rbac","g":"sec","word":"Rollenbasierte Zugriffskontrolle (RBAC)","text":"Zugang nach Rolle vergeben, etwa Betrachter oder Bearbeiter, statt Person für Person.","also":["RBAC","rollenbasierter Zugriff","Role-based Access Control"]},{"id":"vuln","g":"sec","word":"Schwachstelle","text":"Eine Schwäche, die jemand nutzen könnte, um einzubrechen oder Schaden anzurichten.","also":["Schwachstellen","Sicherheitslücke","Verwundbarkeit","Vulnerability"]},{"id":"zeroday","g":"sec","word":"Zero-Day","text":"Eine Schwachstelle, die Angreifer kennen, bevor die Hersteller überhaupt Zeit hatten, sie zu beheben.","also":["Zero-Days","Zero Day","Zero-Day-Lücke"]},{"id":"malware","g":"sec","word":"Malware","text":"Schädliche Software, etwa Viren, die dazu gemacht ist, Schaden anzurichten, auszuspähen oder zu stehlen.","also":["Schadsoftware"]},{"id":"ransomware","g":"sec","word":"Ransomware","text":"Malware, die deine Dateien sperrt und Geld für die Freigabe verlangt. Gute Backups sind die beste Verteidigung.","also":["Erpressungstrojaner","Ransomware-Angriff","Lösegeld-Software"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Gefälschte Nachrichten, die dich dazu bringen wollen, Passwörter oder Geld preiszugeben oder etwas Schädliches zu öffnen.","also":["Phishing-Mail","Phishing-Mails","Phishing-E-Mail"]},{"id":"socialeng","g":"sec","word":"Social Engineering","text":"Menschen statt Computer austricksen, damit sie Zugang geben, etwa durch einen falschen Anruf vom „IT-Support“."},{"id":"firewall","g":"sec","word":"Firewall","text":"Ein Wächter, der entscheidet, welcher Netzwerkverkehr herein- oder hinausdarf.","also":["Firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Kurz für „virtuelles privates Netzwerk“: eine private, verschlüsselte Verbindung über das Internet, oft genutzt, um sicher an Firmensysteme zu kommen.","also":["Virtuelles privates Netzwerk","Virtual Private Network"]},{"id":"ddos","g":"sec","word":"Dienstblockade (DoS, DDoS)","text":"Einen Dienst mit so viel gefälschtem Datenverkehr überfluten, dass echte Leute ihn nicht nutzen können. DDoS heisst, dass er von vielen Computern gleichzeitig kommt.","also":["DoS","DDoS","Denial of Service","DDoS-Angriff"]},{"id":"pentest","g":"sec","word":"Penetrationstest (Pentest)","text":"Freundliche Fachleute beauftragen, die versuchen einzubrechen, damit Schwachstellen gefunden werden, bevor echte Angreifer sie finden.","also":["Pen-Test","Pentest","Penetrationstests","Pentesting"]},{"id":"audit","g":"sec","word":"Sicherheitsaudit","text":"Eine sorgfältige Prüfung, wie gut etwas geschützt ist, anhand einer Liste bewährter Praktiken.","also":["Sicherheitsaudits","Security Audit","Sicherheitsprüfung"]},{"id":"threatmodel","g":"sec","word":"Bedrohungsmodellierung","text":"Durchdenken, wer etwas angreifen könnte, wie, und was du tun würdest, um ihn aufzuhalten.","also":["Threat Modeling","Bedrohungsmodell","Threat Model"]},{"id":"breach","g":"sec","word":"Datenpanne","text":"Wenn private Informationen an Leute gelangen, die sie nicht haben sollten, oder ohne Erlaubnis verloren gehen oder geändert werden.","also":["Datenpannen","Data Breach","Datenleck"]},{"id":"pii","g":"sec","word":"Personenbezogene Daten","text":"Alle Informationen über eine Person, die identifiziert werden kann, etwa Name, E-Mail-Adresse oder Standort. Auf Englisch PII genannt.","also":["PII","personenbezogene Daten"]},{"id":"gdpr","g":"sec","word":"DSGVO","text":"Das europäische Gesetz zu personenbezogenen Daten (Grossbritannien hat eine eigene Fassung): nur sammeln, was du brauchst, sicher aufbewahren und Leute ihre Daten einsehen oder löschen lassen.","also":["GDPR","Datenschutz-Grundverordnung","General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Datenschutz","text":"Personenbezogene Daten ordentlich und im Rahmen des Gesetzes behandeln.","also":["Datenschutzrecht","Data Protection"]},{"id":"privacypolicy","g":"sec","word":"Datenschutzerklärung","text":"Eine öffentliche Seite, die sagt, welche personenbezogenen Daten du sammelst, warum und was du damit machst.","also":["Privacy Policy","Datenschutzhinweis","Datenschutzhinweise"]},{"id":"consent","g":"sec","word":"Einwilligung","text":"Das klare, freie Ja einer Person dazu, dass ihre Daten auf eine bestimmte Weise genutzt werden. Sie kann es jederzeit zurücknehmen.","also":["Opt-in","Zustimmung","Consent"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"Eine kleine Datei, die eine Website in deinem Browser speichert, um sich Dinge zu merken, etwa dass du angemeldet bist. Für manche braucht es zuerst deine Einwilligung.","also":["Cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Datenminimierung","text":"Nur die personenbezogenen Daten sammeln und behalten, die du für die Aufgabe wirklich brauchst.","also":["Datensparsamkeit","Data Minimisation"]},{"id":"retention","g":"sec","word":"Aufbewahrungsdauer","text":"Wie lange Daten aufbewahrt werden, bevor sie gelöscht werden. Sie nicht länger als nötig zu behalten ist sicherer und oft gesetzlich verlangt.","also":["Speicherdauer","Data Retention","Aufbewahrungsfrist"]},{"id":"anon","g":"sec","word":"Anonymisierung","text":"Daten so verändern, dass daraus vernünftigerweise niemand mehr erkannt werden kann.","also":["anonymisiert","anonymisieren","anonyme Daten"]},{"id":"pseudo","g":"sec","word":"Pseudonymisierung","text":"Namen und andere Angaben durch Codes ersetzen, mit einem getrennt aufbewahrten Schlüssel, um sie wieder zuzuordnen. Es bleiben trotzdem personenbezogene Daten.","also":["pseudonymisiert","pseudonymisieren"]},{"id":"dpa","g":"sec","word":"Auftragsverarbeitungsvertrag (AVV)","text":"Ein Vertrag, der regelt, wie ein Dienstleister personenbezogene Daten in deinem Auftrag behandeln darf.","also":["AVV","DPA","Data Processing Agreement"]},{"id":"dpia","g":"sec","word":"Datenschutz-Folgenabschätzung (DSFA)","text":"Ein sorgfältiger Blick vor dem Start darauf, wie ein Plan zur Nutzung personenbezogener Daten Menschen betreffen könnte und wie man die Risiken senkt.","also":["DSFA","DPIA","Data Protection Impact Assessment"]},{"id":"auditlog","g":"sec","word":"Audit-Log","text":"Eine Aufzeichnung, wer wann was getan hat, damit man Handlungen später nachprüfen kann.","also":["Audit-Logs","Audit Trail","Prüfprotokoll","Änderungsprotokoll"]},{"id":"compliance","g":"sec","word":"Compliance","text":"Die Gesetze, Regeln und Standards einhalten, die für dich gelten, und zeigen können, dass du es tust.","also":["konform","Regelkonformität"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"Ein bekannter internationaler Standard für das Management von Informationssicherheit. Firmen können sich danach zertifizieren lassen.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"Ein US-Bericht, von externen Prüfern kontrolliert, der zeigt, dass eine Firma mit Kundendaten ordentlich umgeht.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agent","text":"Eine KI, die eine Aufgabe selbstständig erledigt: liest den Code, macht Änderungen, führt Prüfungen aus und meldet sich zurück.","also":["Agenten","Agents"]},{"id":"token","g":"ai","word":"Token","text":"Die Einheit, in der KI-Nutzung gezählt wird: grob ein paar Buchstaben gelesenen oder geschriebenen Texts. Weniger Tokens, mehr bleibt von deinem Tarif.","also":["Tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"Ein kleiner Befehl, der zu einem bestimmten Zeitpunkt von selbst läuft, z. B. wenn eine KI-Sitzung startet, damit das Team deine Kommentare mitbekommt.","also":["Hooks"]},{"id":"ai","g":"ai","word":"Künstliche Intelligenz (KI)","text":"Computersysteme, die Dinge tun, für die man normalerweise einen Menschen braucht, etwa schreiben, Fragen beantworten oder Bilder erkennen.","also":["KI","AI","Artificial Intelligence"],"noTip":1},{"id":"ml","g":"ai","word":"Maschinelles Lernen (ML)","text":"Eine Art, Computer aus vielen Beispielen Muster lernen zu lassen, statt ihnen genaue Regeln zu geben.","also":["Machine Learning","ML"]},{"id":"model","g":"ai","word":"Modell","text":"Das trainierte „Gehirn“ eines KI-Systems, entstanden durch das Lernen aus riesigen Mengen an Beispielen. Modelle unterscheiden sich in Können, Tempo und Preis.","also":["Modelle","KI-Modell","Model"],"noTip":1},{"id":"llm","g":"ai","word":"Grosses Sprachmodell (LLM)","text":"Ein KI-Modell, das mit riesigen Textmengen trainiert wurde, sodass es Sprache lesen und schreiben kann.","also":["LLM","LLMs","Large Language Model"]},{"id":"genai","g":"ai","word":"Generative KI","text":"KI, die Neues erschafft, etwa Texte, Bilder oder Code, statt Dinge nur zu sortieren oder zu erkennen.","also":["GenAI","generative AI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"Ein Programm, mit dem du in Alltagssprache sprichst, per Tippen oder Sprechen.","also":["Chatbots"]},{"id":"prompt","g":"ai","word":"Prompt","text":"Das, was du einer KI gibst: deine Frage oder Anweisungen, dazu alles, was du ihr reichst. Klarere Prompts bringen meist bessere Antworten.","also":["Prompts","Eingabeaufforderung"]},{"id":"prompteng","g":"ai","word":"Prompt Engineering","text":"Die Kunst, Prompts zu schreiben, die verlässliche, nützliche Ergebnisse bringen.","also":["Prompts schreiben"]},{"id":"sysprompt","g":"ai","word":"System-Prompt","text":"Hintergrundanweisungen, die eine KI bekommt, bevor das Gespräch beginnt, und die ihre Rolle und Regeln festlegen. Sie wiegen schwerer als das, was du tippst.","also":["System-Prompts","Systemanweisung","Systemanweisungen"]},{"id":"context","g":"ai","word":"Kontext","text":"Alles, was die KI sehen kann, während sie arbeitet: die Anweisungen, deine Nachrichten, gelesene Dateien und frühere Antworten.","noTip":1},{"id":"ctxwin","g":"ai","word":"Kontextfenster","text":"Wie viel eine KI auf einmal im Kopf behalten kann, in Tokens gemessen. Darüber hinaus werden ältere Teile weggelassen oder zusammengefasst.","also":["Kontextfenster","Context Window"]},{"id":"session","g":"ai","word":"Sitzung","text":"Ein Arbeitsgespräch mit einer KI, vom Anfang bis zum Ende. Eine neue Sitzung beginnt mit frischem Gedächtnis.","also":["Sitzungen","Session","Sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Gedächtnis","text":"Notizen, die eine KI zwischen Sitzungen aufbewahrt, damit sie sich an deine Vorlieben und frühere Entscheidungen erinnert.","noTip":1},{"id":"hallucination","g":"ai","word":"Halluzination","text":"Wenn eine KI etwas sagt, das sehr sicher klingt, aber erfunden oder falsch ist. Prüf wichtige Fakten nach.","also":["Halluzinationen","halluzinieren","halluziniert"]},{"id":"training","g":"ai","word":"Training","text":"Einem Modell etwas beibringen, indem man ihm riesige Mengen an Beispielen zeigt, bevor es jemand benutzt.","also":["trainiert","Trainieren"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Trainingsdaten","text":"Die Beispiele, aus denen ein Modell gelernt hat. Sein Wissen endet an dem Tag, an dem diese Daten gesammelt wurden.","also":["Trainingsdatensatz","Training Data"]},{"id":"cutoff","g":"ai","word":"Wissensstichtag","text":"Das Datum, an dem das eingebaute Wissen einer KI endet. Von späteren Dingen weiss sie nichts, es sei denn, sie schlägt sie nach.","also":["Knowledge Cutoff","Trainingsstichtag","Wissensgrenze"]},{"id":"finetune","g":"ai","word":"Feinabstimmung (Fine-Tuning)","text":"Zusätzliches Training eines bestehenden Modells mit deinen eigenen Beispielen, damit es bei einer bestimmten Aufgabe besser wird.","also":["Fine-Tuning","Fine Tuning","feinabgestimmt","Feintuning"]},{"id":"inference","g":"ai","word":"Inferenz","text":"Wenn ein KI-Modell tatsächlich benutzt wird, um etwas zu beantworten, im Gegensatz zum Training.","also":["Inference","Modellinferenz"]},{"id":"tooluse","g":"ai","word":"Werkzeugnutzung","text":"Eine KI, die nicht nur reden, sondern auch etwas tun kann: Befehle ausführen, Dateien lesen oder im Web suchen, mit Werkzeugen, die die App ihr gibt.","also":["Tool Use","Tool Calling","Tool Call","Tool-Aufrufe","Werkzeugaufruf"]},{"id":"subagent","g":"ai","word":"Subagent","text":"Eine Helfer-KI, der eine Haupt-KI eine kleinere Aufgabe übergibt und von der sie das Ergebnis zurückbekommt.","also":["Subagenten","Sub-Agent","Unteragent"]},{"id":"multiagent","g":"ai","word":"Multi-Agent","text":"Mehrere KIs arbeiten gemeinsam an einer Aufgabe, jede mit ihrem eigenen Teil, wie ein kleines Team.","also":["Multi-Agent-System","Multiagentensystem"]},{"id":"autonomy","g":"ai","word":"Autonomie","text":"Wie viel eine KI von sich aus tun darf, bevor sie einen Menschen fragen muss.","also":["autonom","Selbstständigkeit"]},{"id":"hitl","g":"ai","word":"Human in the Loop","text":"Einen Menschen beteiligt halten, der an wichtigen Stellen prüft oder freigibt, was die KI tut. In AI-gile bist das du.","also":["Human-in-the-Loop","HITL","Mensch in der Schleife"]},{"id":"guardrails","g":"ai","word":"Leitplanken","text":"Grenzen und Prüfungen, die die Handlungen einer KI sicher halten, etwa dass vor dem Livegehen eine Freigabe nötig ist. Sie senken das Fehlerrisiko, schliessen Fehler aber nicht aus.","also":["Guardrails","Guardrail","Schutzplanken"]},{"id":"rag","g":"ai","word":"Retrieval-Augmented Generation (RAG)","text":"Eine KI in deinen eigenen Dokumenten nachschlagen lassen, bevor sie antwortet, damit ihre Antworten auf deinen Fakten beruhen.","also":["RAG","Retrieval Augmented Generation","abrufgestützte Generierung"]},{"id":"embedding","g":"ai","word":"Embedding","text":"Text in eine Liste von Zahlen verwandeln, die seine Bedeutung festhält, damit ein Computer Dinge mit ähnlicher Bedeutung finden kann.","also":["Embeddings","Einbettung"]},{"id":"vectordb","g":"ai","word":"Vektordatenbank","text":"Eine Datenbank, die dafür gebaut ist, diese Zahlenlisten (Embeddings) zu durchsuchen, um Material mit ähnlicher Bedeutung zu finden.","also":["Vektordatenbanken","Vector Database","Vector Store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"Ein gängiger Standard, um Werkzeuge und Datenquellen an KI-Apps anzuschliessen, damit eine KI sie nutzen kann.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperatur","text":"Eine Einstellung dafür, wie abenteuerlich die Antworten einer KI sind. Niedrig sorgt für gleichmässigere, vorhersehbarere Antworten, hoch für abwechslungsreichere. Keines von beiden macht sie immer richtig.","also":["Modelltemperatur","Temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodal","text":"Fähig, mit mehr als einer Art von Information zu arbeiten, etwa Text, Bildern und Ton.","also":["multi-modal","mehrmodal"]},{"id":"evals","g":"ai","word":"Evaluierung (Eval)","text":"Ein geplanter Test, wie gut eine KI bei ausgewählten Beispielen abschneidet, damit du Modelle oder Prompts vergleichen kannst.","also":["Eval","Evals","Evaluationen","Evaluierungen"]},{"id":"bias","g":"ai","word":"Verzerrung (Bias)","text":"Wenn eine KI (oder ein Mensch) unfair in eine Richtung neigt, oft wegen dessen, woraus sie gelernt hat.","also":["Bias","voreingenommen","Vorurteil"],"noTip":1},{"id":"responsible","g":"ai","word":"Verantwortungsvolle KI","text":"KI fair, sicher und ehrlich einsetzen, wobei Menschen weiter für die Ergebnisse geradestehen.","also":["ethische KI","Responsible AI"]},{"id":"injection","g":"ai","word":"Prompt Injection","text":"Ein Trick, bei dem versteckte Anweisungen in einer Webseite oder Datei eine KI dazu bringen wollen, etwas zu tun, worum ihr Nutzer nicht gebeten hat.","also":["Prompt Injections","Prompt-Einschleusung"]},{"id":"ratelimit","g":"ai","word":"Ratenbegrenzung","text":"Eine Obergrenze, wie viele Anfragen du in einer bestimmten Zeit an einen Dienst schicken darfst. Wer sie überschreitet, muss warten.","also":["Rate Limit","Rate Limits","Anfragelimit","begrenzt"]},{"id":"usagelimit","g":"ai","word":"Nutzungslimit","text":"Wie viel KI-Arbeit dein Tarif in einem Zeitraum erlaubt; danach ist Pause, oder es kostet mehr.","also":["Nutzungslimits","Usage Limit","Verbrauchslimit"]},{"id":"vibe","g":"ai","word":"Vibe Coding","text":"Software hauptsächlich bauen, indem man einer KI beschreibt, was man will, und sie den Code schreiben lässt.","also":["Vibe-Coding","Vibecoding"]},{"id":"budget","g":"money","word":"Budget","text":"Der Geldbetrag, der für etwas beiseitegelegt ist.","also":["Budgets"],"noTip":1},{"id":"costest","g":"money","word":"Kostenschätzung","text":"Eine möglichst gute Vermutung, was etwas kosten wird, bevor du anfängst.","also":["Kostenschätzungen","Cost Estimate"]},{"id":"roi","g":"money","word":"Kapitalrendite (ROI)","text":"Was du zurückbekommst im Vergleich zu dem, was du hineingesteckt hast. Ist es positiv, hat es sich gelohnt.","also":["ROI","Return on Investment","Rendite"]},{"id":"tco","g":"money","word":"Gesamtbetriebskosten (TCO)","text":"Alles, was etwas über seine ganze Lebensdauer wirklich kostet, nicht nur der Kaufpreis: Betrieb, Support, Upgrades und am Ende die Ausserbetriebnahme.","also":["TCO","Total Cost of Ownership"]},{"id":"capex","g":"money","word":"CapEx und OpEx","text":"CapEx ist Geld, das du im Voraus für Dinge ausgibst, die du behältst; OpEx sind laufende Ausgaben, wie monatliche Rechnungen.","also":["CapEx","OpEx","Investitionsausgaben","Betriebsausgaben"]},{"id":"subscription","g":"money","word":"Abo","text":"Regelmässig zahlen, meist monatlich oder jährlich, um etwas weiter nutzen zu dürfen.","also":["Abos","Abonnement","Subscription"],"noTip":1},{"id":"saas","g":"money","word":"Software as a Service (SaaS)","text":"Software, die du online nutzt und per Abo bezahlst, während der Hersteller sie für dich betreibt.","also":["SaaS","Software als Dienst"]},{"id":"payg","g":"money","word":"Nutzungsabhängige Abrechnung","text":"Nur für das zahlen, was du nutzt, wie bei Cloud-Computing oder KI-Tokens.","also":["Pay as you go","Pay-as-you-go","nutzungsbasierte Preise"]},{"id":"overage","g":"money","word":"Mehrverbrauch","text":"Nutzung über das hinaus, was dein Tarif enthält; sie kann extra kosten.","also":["Overage","Mehrverbrauchskosten","Überschreitung"]},{"id":"billingalert","g":"money","word":"Abrechnungswarnung","text":"Eine Nachricht, wenn Ausgaben oder Nutzung eine von dir gewählte Marke erreichen. Sie warnt dich, stoppt aber nicht immer weitere Kosten.","also":["Abrechnungswarnungen","Billing Alert","Ausgabenwarnung"]},{"id":"freetier","g":"money","word":"Gratisstufe","text":"Eine kostenlose Stufe eines kostenpflichtigen Dienstes, mit Grenzen. Praktisch für den Anfang.","also":["Free Tier","kostenloser Tarif","Gratistarif"]},{"id":"pricing","g":"money","word":"Preismodell","text":"Die verschiedenen Pakete, die ein Dienst verkauft, jedes mit eigenem Preis und eigenen Grenzen.","also":["Preismodelle","Pricing Plan","Tarif","Tarife"]},{"id":"licence","g":"money","word":"Lizenz","text":"Die Regeln, wie du etwas, das jemand anderes gemacht hat, nutzen, kopieren, ändern oder weitergeben darfst, etwa Software, Schriftarten oder Bilder.","also":["Lizenzen","License","Licence"],"noTip":1},{"id":"opensource","g":"money","word":"Open Source","text":"Software, deren Code jeder lesen, nutzen und oft kostenlos ändern darf, nach den Regeln ihrer Lizenz.","also":["Open-Source","quelloffen","Open-Source-Software","OSS"]},{"id":"osslicence","g":"money","word":"Open-Source-Lizenz","text":"Die Regeln, die zu Open-Source-Code gehören. Manche erlauben fast alles (wie MIT), andere verlangen, dass du auch deine Änderungen teilst (wie GPL).","also":["Open-Source-Lizenzen","MIT-Lizenz","GPL"]},{"id":"proprietary","g":"money","word":"Proprietär","text":"Im Besitz einer Firma und nicht frei kopier- oder änderbar. Das Gegenteil von Open Source.","also":["proprietäre Software","Proprietary","Closed Source"]},{"id":"copyright","g":"money","word":"Urheberrecht","text":"Das gesetzliche Recht eines Urhebers, Kopien seines Werks zu kontrollieren, auch von Code und Texten.","also":["Copyright","urheberrechtlich geschützt"],"noTip":1},{"id":"ip","g":"money","word":"Geistiges Eigentum (IP)","text":"Ideen und Schöpfungen, die das Gesetz als Eigentum behandelt, etwa Code, Designs, Namen und Logos.","also":["IP","Intellectual Property"]},{"id":"tos","g":"money","word":"Nutzungsbedingungen","text":"Die Regeln, denen du zustimmst, wenn du einen Dienst nutzt.","also":["AGB","Terms of Service","Allgemeine Geschäftsbedingungen"]},{"id":"contract","g":"money","word":"Vertrag","text":"Eine schriftliche Vereinbarung zwischen zwei Seiten, die rechtlich bindend ist.","also":["Verträge","Contract"],"noTip":1},{"id":"sow","g":"money","word":"Leistungsbeschreibung (SOW)","text":"Ein Dokument, das genau festhält, welche Arbeit bis wann und für wie viel gemacht wird.","also":["SOW","Statement of Work","Arbeitsbeschreibung"]},{"id":"fixedprice","g":"money","word":"Festpreis","text":"Ein vereinbarter Preis für die ganze Arbeit, egal wie lange sie dauert.","also":["Fixpreis","Fixed Price"]},{"id":"tm","g":"money","word":"Abrechnung nach Aufwand","text":"Die tatsächlich gearbeiteten Stunden und das wirklich Verbrauchte bezahlen, statt eines festen Preises.","also":["Time and Materials","T&M","nach Aufwand"]},{"id":"invoice","g":"money","word":"Rechnung","text":"Eine Aufforderung zur Zahlung für geleistete Arbeit oder gelieferte Waren.","also":["Rechnungen","Invoice"],"noTip":1},{"id":"lockin","g":"money","word":"Anbieterbindung","text":"Wenn ein Wechsel zu einem anderen Anbieter so schwer oder teuer ist, dass du am bisherigen festhängst.","also":["Vendor Lock-in","Lock-in","Abhängigkeit vom Anbieter"]},{"id":"procurement","g":"money","word":"Beschaffung","text":"Der Vorgang, Anbieter auszuwählen und bei ihnen zu kaufen.","also":["Einkauf","Procurement"]},{"id":"servicecredit","g":"money","word":"Service-Gutschrift","text":"Geld zurück oder ein Rabatt, den du bekommst, wenn ein Anbieter sein SLA verfehlt.","also":["Service Credit","Service Credits","Gutschrift"]}]}};
